export enum ShockType {
  // ========================================
  // BLACK SWAN (0.1% per month)
  // Civilization-altering, difficult/impossible recovery
  // ========================================

  /**
   * Full-scale nuclear war
   * Effect: 50-99% mortality, instant or rapid (1-6 months)
