  }

  // Record shock in history
  state.history.exogenousShocks = state.history.exogenousShocks || [];
  state.history.exogenousShocks.push({
    month: state.currentMonth,
    type: shockType,
    severity: calculateShockSeverity(state, shockType),
  });
}

