   136→        ? 'No clear peaks detected (uniform distribution)'
   137→        : 'Single peak detected (unimodal distribution)',
   138→    };
   139→  }
   140→
   141→  // Find valley between two largest peaks
   142→  const peaksByHeight = peaks.sort((a, b) => counts[b] - counts[a]);
   143→  const peak1 = peaksByHeight[0];
   144→  const peak2 = peaksByHeight[1];
   145→  const [leftPeak, rightPeak] = peak1 < peak2 ? [peak1, peak2] : [peak2, peak1];
   146→
   147→  // Find minimum between peaks
   148→  let valleyIndex = leftPeak;
   149→  let valleyCount = counts[leftPeak];
   150→  for (let i = leftPeak + 1; i <= rightPeak; i++) {
