   157→  // Calculate valley depth (normalized)
   158→  const leftPeakHeight = counts[leftPeak];
   159→  const rightPeakHeight = counts[rightPeak];
   160→  const avgPeakHeight = (leftPeakHeight + rightPeakHeight) / 2;
   161→  const valleyDepth = (avgPeakHeight - valleyCount) / avgPeakHeight;
   162→
   163→  // Assess bimodality confidence
   164→  let isBimodal = false;
   165→  let confidence: 'low' | 'medium' | 'high' = 'low';
   166→  let explanation = '';
   167→
   168→  if (valleyDepth > 0.5) {
   169→    isBimodal = true;
   170→    confidence = 'high';
   171→    explanation = `Strong bimodal distribution detected (valley depth ${(valleyDepth * 100).toFixed(1)}%, ${peaks.length} peaks). Suggests two distinct outcome regimes (e.g., survivors vs collapsed states).`;
