   173→    isBimodal = true;
   174→    confidence = 'medium';
   175→    explanation = `Moderate bimodal distribution detected (valley depth ${(valleyDepth * 100).toFixed(1)}%, ${peaks.length} peaks). May indicate crisis cascade effects.`;
