   177→    isBimodal = false;
   178→    confidence = 'low';
   179→    explanation = `Weak bimodal signal detected (valley depth ${(valleyDepth * 100).toFixed(1)}%, ${peaks.length} peaks). Insufficient evidence for distinct modes.`;
