   230→export function generateAsciiHistogram(
   231→  values: number[],
   232→  binCount: number = 20,
   233→  maxBarWidth: number = 50,
   234→  label?: string
   235→): string {
   236→  if (values.length === 0) return 'No data to visualize';
   237→
   238→  const bins = createHistogramBins(values, binCount);
   239→  const maxCount = Math.max(...bins.map(b => b.count));
   240→
   241→  let output = '';
   242→  if (label) {
