   251→    const labelMax = bin.max.toFixed(1).padStart(6);
   252→    const countStr = bin.count.toString().padStart(4);
   253→    const pctStr = `${bin.percentage.toFixed(1)}%`.padStart(6);
   254→
   255→    output += `${labelMin} - ${labelMax} | ${bar} ${countStr} (${pctStr})\n`;
   256→  }
   257→
   258→  return output;
   259→}
