   275→  report += `📊 ${metricName} DISTRIBUTION ANALYSIS (N=${values.length})\n`;
   276→  report += `${'='.repeat(80)}\n\n`;
   277→
   278→  // Summary statistics
   279→  report += `📈 SUMMARY STATISTICS:\n`;
   280→  report += `  Mean:     ${(stats.mean * 100).toFixed(1)}${unit}\n`;
   281→  report += `  Median:   ${(stats.median * 100).toFixed(1)}${unit}\n`;
   282→  report += `  Std Dev:  ${(stats.std * 100).toFixed(1)}${unit}\n`;
   283→  report += `  Min:      ${(stats.min * 100).toFixed(1)}${unit}\n`;
   284→  report += `  Max:      ${(stats.max * 100).toFixed(1)}${unit}\n`;
   285→  report += `  Q1:       ${(stats.q1 * 100).toFixed(1)}${unit}\n`;
   286→  report += `  Q3:       ${(stats.q3 * 100).toFixed(1)}${unit}\n`;
   287→  report += `  IQR:      ${(stats.iqr * 100).toFixed(1)}${unit}\n`;
   288→  report += `\n`;
   289→
   290→  // Distribution shape
   291→  report += `📐 DISTRIBUTION SHAPE:\n`;
   292→  report += `  Coefficient of Variation: ${(stats.coefficientOfVariation * 100).toFixed(1)}%\n`;
   293→  report += `    ${interpretCV(stats.coefficientOfVariation)}\n`;
   294→  report += `  Skewness: ${stats.skewness.toFixed(3)}\n`;
   295→  report += `    ${interpretSkewness(stats.skewness)}\n`;
   296→  report += `  Kurtosis: ${stats.kurtosis.toFixed(3)}\n`;
   297→  report += `    ${interpretKurtosis(stats.kurtosis)}\n`;
   298→  report += `\n`;
   299→
   300→  // Bimodality analysis
   301→  report += `🔬 BIMODALITY ANALYSIS:\n`;
   302→  report += `  Bimodal: ${bimodality.isBimodal ? 'YES' : 'NO'} (confidence: ${bimodality.confidence})\n`;
   303→  report += `  Peak Count: ${bimodality.peakCount}\n`;
   304→  report += `  Valley Depth: ${(bimodality.valleyDepth * 100).toFixed(1)}%\n`;
   305→  report += `  ${bimodality.explanation}\n`;
   306→  report += `\n`;
   307→
   308→  // ASCII histogram
   309→  report += generateAsciiHistogram(values, 20, 50, `📊 DISTRIBUTION HISTOGRAM`);
   310→
   311→  // Interpretation
   312→  report += `\n\n💡 INTERPRETATION:\n`;
   313→  if (bimodality.isBimodal && bimodality.confidence !== 'low') {
   314→    report += `  ⚠️  BIMODAL DISTRIBUTION DETECTED\n`;
   315→    report += `  This suggests TWO DISTINCT OUTCOME REGIMES:\n`;
   316→    report += `  - Likely cause: Crisis cascades (environmental/social tipping points)\n`;
   317→    report += `  - Some seeds hit tipping points → mass disruption (high ${metricName})\n`;
   318→    report += `  - Other seeds avoid cascades → stability (low ${metricName})\n`;
   319→    report += `  - Recommendation: Investigate crisis correlation, add stabilization mechanisms\n`;
   320→  } else if (stats.coefficientOfVariation > 0.5) {
   321→    report += `  ⚠️  EXTREME VARIANCE (CV > 50%)\n`;
   322→    report += `  This suggests CHAOTIC DYNAMICS:\n`;
   323→    report += `  - Likely cause: Butterfly effects, exponential RNG sensitivity\n`;
   324→    report += `  - Missing negative feedback loops or automatic stabilizers\n`;
   325→    report += `  - Recommendation: Add homeostasis mechanisms, dampen oscillations\n`;
   326→  } else if (stats.coefficientOfVariation > 0.3) {
   327→    report += `  ℹ️  MODERATE VARIANCE (CV 30-50%)\n`;
   328→    report += `  This may represent REALISTIC HISTORICAL CONTINGENCY:\n`;
   329→    report += `  - Random events, policy choices, tipping points matter\n`;
   330→    report += `  - Similar to real-world variation across countries/eras\n`;
   331→    report += `  - Recommendation: Validate variance is research-backed, not artifact\n`;
   332→  } else {
   333→    report += `  ✅ LOW VARIANCE (CV < 30%)\n`;
   334→    report += `  This suggests ROBUST PATTERNS:\n`;
   335→    report += `  - Outcomes converge despite different initial conditions\n`;
   336→    report += `  - Policy effects are consistent and predictable\n`;
   337→    report += `  - Good for research validation and policy recommendations\n`;
   338→  }
   339→
   340→  return report;
   341→}
   342→
   343→/**
   344→ * Interpret coefficient of variation
   345→ */
   346→function interpretCV(cv: number): string {
   347→  if (cv > 1.0) return '❌ EXTREME VARIANCE (CV > 100% - more variance than mean!)';
   348→  if (cv > 0.5) return '⚠️  Very high variance (CV > 50% - outcomes highly unpredictable)';
   349→  if (cv > 0.3) return 'ℹ️  Moderate variance (CV 30-50% - substantial variation)';
   350→  if (cv > 0.15) return '✅ Low variance (CV 15-30% - relatively stable)';
   351→  return '✅ Very low variance (CV < 15% - highly stable)';
   352→}
   353→
   354→/**
   355→ * Interpret skewness
   356→ */
   357→function interpretSkewness(skew: number): string {
   358→  if (Math.abs(skew) < 0.5) return '✅ Approximately symmetric distribution';
   359→  if (skew > 1) return '⚠️  Strongly right-skewed (long tail of high values)';
   360→  if (skew > 0.5) return 'ℹ️  Moderately right-skewed';
   361→  if (skew < -1) return '⚠️  Strongly left-skewed (long tail of low values)';
   362→  return 'ℹ️  Moderately left-skewed';
   363→}
   364→
   365→/**
   366→ * Interpret kurtosis
   367→ */
   368→function interpretKurtosis(kurt: number): string {
   369→  if (Math.abs(kurt) < 0.5) return '✅ Normal kurtosis (similar to bell curve)';
   370→  if (kurt > 3) return '⚠️  Very heavy tails (many extreme outliers)';
   371→  if (kurt > 1) return 'ℹ️  Heavy tails (more outliers than normal)';
   372→  if (kurt < -1) return 'ℹ️  Light tails (fewer outliers than normal)';
   373→  return '✅ Slight deviation from normal';
   374→}
   375→
   376→/**
   377→ * Identify outliers using IQR method
   378→ */
   379→export function identifyOutliers(values: number[]): { outliers: number[]; indices: number[] } {
   380→  const stats = calculateDistributionStats(values);
   381→  const lowerBound = stats.q1 - 1.5 * stats.iqr;
   382→  const upperBound = stats.q3 + 1.5 * stats.iqr;
   383→
   384→  const outliers: number[] = [];
   385→  const indices: number[] = [];
   386→
   387→  values.forEach((v, i) => {
   388→    if (v < lowerBound || v > upperBound) {
   389→      outliers.push(v);
   390→      indices.push(i);
   391→    }
   392→  });
   393→
   394→  return { outliers, indices };
   395→}
