      const scarcityIncrement = 0.08 * (utopianConditions ? productivityMultiplier : 1.0);
      newStage = Math.min(4.0, currentStage + scarcityIncrement);
      transitioned = true;
      transitionType = utopianConditions ? 'natural' : 'policy';
    }
  }

  return {
    newStage,
    transitioned,
    transitionType
  };
}

