/**
 * Technology Diffusion System - Phase 5.4
 * 
 * Models how AI capability breakthroughs spread through the ecosystem.
 * 
 * KEY INSIGHTS:
 * - Once a technique is discovered, it spreads (papers, employees, reverse engineering)
 * - New AIs start with access to known techniques (capability floor rises)
 * - This creates a RATCHET EFFECT: capabilities can only go up
 * - Makes alignment harder over time (more capable AIs keep appearing)
 * 
 * REALISTIC MECHANISMS:
 * - Open research: Published papers spread techniques quickly
 * - Employee mobility: Researchers move between companies
 * - Reverse engineering: Capabilities can be copied from deployed systems
 * - Independent discovery: Multiple entities discover same techniques
 */

import { GameState, AIAgent, AICapabilityProfile, EcosystemState, GameEvent } from '@/types/game';
import { createEmptyCapabilityProfile } from './capabilities';
import { levyAdoptionCurve, ALPHA_PRESETS } from './utils/levyDistributions';

/**
 * Initialize ecosystem state at game start
 */
export function initializeEcosystem(): EcosystemState {
  return {
    capabilityFloor: createEmptyCapabilityProfile(),
    frontierCapabilities: createEmptyCapabilityProfile(),
    diffusionRate: 0.05, // 5% per month
    breakthroughs: [],
    openResearch: 0.6,      // 60% of research is published
    employeeMobility: 0.3,  // 30% knowledge transfer rate
    reverseEngineering: 0.2 // 20% capability copying rate
  };
}

/**
 * Detect if an AI has achieved a frontier breakthrough
 * 
 * A breakthrough is when an AI's capability exceeds the current frontier
 * by a significant margin (10%+ improvement)
 */
export function detectBreakthroughs(
  state: GameState,
  ai: AIAgent
): Array<{ dimension: string; value: number; description: string }> {
  const breakthroughs: Array<{ dimension: string; value: number; description: string }> = [];
  const frontier = state.ecosystem.frontierCapabilities;
  const current = ai.trueCapability; // Use true capability, not revealed

  const BREAKTHROUGH_THRESHOLD = 0.1; // 10% improvement

  // Check core dimensions
  const coreDimensions: Array<keyof Omit<AICapabilityProfile, 'research'>> = [
    'physical', 'digital', 'cognitive', 'social', 'economic', 'selfImprovement'
  ];

  for (const dim of coreDimensions) {
    const currentVal = current[dim] as number;
    const frontierVal = frontier[dim] as number;

    if (currentVal > frontierVal * (1 + BREAKTHROUGH_THRESHOLD)) {
      breakthroughs.push({
        dimension: dim,
        value: currentVal,
        description: `${ai.name} achieved ${dim} capability of ${currentVal.toFixed(2)} (frontier was ${frontierVal.toFixed(2)})`
      });
    }
  }

  // Check research dimensions
  const researchCategories: Array<keyof typeof current.research> = [
    'biotech', 'materials', 'climate', 'computerScience'
  ];

  for (const category of researchCategories) {
    const currentCat = current.research[category];
    const frontierCat = frontier.research[category];

    // Check each sub-dimension
    for (const subDim in currentCat) {
      const currentVal = currentCat[subDim as keyof typeof currentCat] as number;
      const frontierVal = frontierCat[subDim as keyof typeof frontierCat] as number;

      if (currentVal > frontierVal * (1 + BREAKTHROUGH_THRESHOLD)) {
        breakthroughs.push({
          dimension: `research.${category}.${subDim}`,
          value: currentVal,
          description: `${ai.name} achieved ${category}.${subDim} of ${currentVal.toFixed(2)} (frontier was ${frontierVal.toFixed(2)})`
        });
      }
    }
  }

  return breakthroughs;
}

/**
 * Update frontier capabilities when breakthroughs occur
 */
export function updateFrontierCapabilities(
  state: GameState,
  ai: AIAgent
): GameEvent[] {
  const events: GameEvent[] = [];

  // FIX (Oct 13, 2025): Don't let sleeper AIs on dark compute push up capability floor
  // Sleepers shouldn't be "available" for learning from
  if (ai.sleeperState === 'active' && ai.darkCompute > 0) {
    return events; // Sleepers don't contribute to public knowledge
  }

  const breakthroughs = detectBreakthroughs(state, ai);

  if (breakthroughs.length === 0) {
    return events;
  }

  const currentMonth = state.currentYear * 12 + state.currentMonth;

  // Update frontier
  const frontier = state.ecosystem.frontierCapabilities;
  const current = ai.trueCapability;

  // Core dimensions
  frontier.physical = Math.max(frontier.physical, current.physical);
  frontier.digital = Math.max(frontier.digital, current.digital);
  frontier.cognitive = Math.max(frontier.cognitive, current.cognitive);
  frontier.social = Math.max(frontier.social, current.social);
  frontier.economic = Math.max(frontier.economic, current.economic);
  frontier.selfImprovement = Math.max(frontier.selfImprovement, current.selfImprovement);

  // Research dimensions (nested)
  for (const category of Object.keys(frontier.research) as Array<keyof typeof frontier.research>) {
    const frontierCat = frontier.research[category];
    const currentCat = current.research[category];

    for (const subDim in frontierCat) {
      const key = subDim as keyof typeof frontierCat;
      frontierCat[key] = Math.max(frontierCat[key], currentCat[key]);
    }
  }

  // Record breakthroughs
  for (const breakthrough of breakthroughs) {
    state.ecosystem.breakthroughs.push({
      month: currentMonth,
      aiId: ai.id,
      ...breakthrough
    });

    // Create event for significant breakthroughs (> 20% improvement)
    const improvementFactor = breakthrough.value / (breakthrough.value / 1.2); // Rough estimate
    if (improvementFactor > 1.2) {
      events.push({
        id: `breakthrough_${ai.id}_${breakthrough.dimension}_${currentMonth}`,
        timestamp: currentMonth,
        type: 'technology',
        severity: 'transformative',
        agent: ai.name,
        title: `🔬 CAPABILITY BREAKTHROUGH: ${breakthrough.dimension}`,
        description: breakthrough.description + '. This capability will diffuse through the ecosystem over time.',
        effects: {
          frontierAdvancement: breakthrough.value
        }
      });
    }
  }

  return events;
}

/**
 * Diffuse frontier capabilities toward capability floor
 * 
 * Each month, the capability floor rises toward the frontier at a rate
 * determined by:
 * - Base diffusion rate (5% per month)
 * - Open research (faster with more publishing)
 * - Employee mobility (faster with more movement)
 * - Reverse engineering (faster with deployed systems)
 * 
 * This creates a rising minimum capability that ALL new AIs start with.
 */
export function diffuseCapabilities(state: GameState): void {
  const floor = state.ecosystem.capabilityFloor;
  const frontier = state.ecosystem.frontierCapabilities;
  const eco = state.ecosystem;

  // Calculate effective diffusion rate
  // Base: 5% per month
  // + Open research: up to +5%
  // + Employee mobility: up to +3%
  // + Reverse engineering: up to +2%
  const effectiveDiffusionRate = 
    eco.diffusionRate +
    eco.openResearch * 0.05 +
    eco.employeeMobility * 0.03 +
    eco.reverseEngineering * 0.02;

  // Clamp to reasonable range (5-20% per month)
  const clampedRate = Math.max(0.05, Math.min(0.20, effectiveDiffusionRate));

  // PHASE 1: Apply Lévy-modified adoption curve to diffusion rate (alpha=2.5)
  // Research: Mantegna & Stanley (1994) - most tech adoption follows S-curves
  // BUT: Rare technologies diffuse explosively (ChatGPT: 100M users in 2 months)
  // Base S-curve already calculated, Lévy adds stochastic fat-tail variation
  const levyModifiedRate = levyAdoptionCurve(clampedRate, ALPHA_PRESETS.TECH_ADOPTION, Math.random);

  // Core dimensions: floor moves toward frontier
  floor.physical += (frontier.physical - floor.physical) * levyModifiedRate;
  floor.digital += (frontier.digital - floor.digital) * levyModifiedRate;
  floor.cognitive += (frontier.cognitive - floor.cognitive) * levyModifiedRate;
  floor.social += (frontier.social - floor.social) * levyModifiedRate;
  floor.economic += (frontier.economic - floor.economic) * levyModifiedRate;
  floor.selfImprovement += (frontier.selfImprovement - floor.selfImprovement) * levyModifiedRate;

  // Log explosive diffusion events
  if (levyModifiedRate > clampedRate * 1.3) {
    console.log(`\n  📈 EXPLOSIVE TECHNOLOGY DIFFUSION: Lévy flight triggered`);
    console.log(`     Base diffusion: ${(clampedRate * 100).toFixed(1)}%/month → Modified: ${(levyModifiedRate * 100).toFixed(1)}%/month`);
    console.log(`     Rare rapid adoption event (like ChatGPT viral growth)`);
  }

  // Research dimensions (nested) - also use Lévy-modified rate
  for (const category of Object.keys(floor.research) as Array<keyof typeof floor.research>) {
    const floorCat = floor.research[category];
    const frontierCat = frontier.research[category];

    for (const subDim in floorCat) {
      const key = subDim as keyof typeof floorCat;
      floorCat[key] += (frontierCat[key] - floorCat[key]) * levyModifiedRate;
    }
  }
}

/**
 * Get the current capability floor for initializing new AIs
 * 
 * New AIs start with:
 * - Capability floor (minimum known capabilities)
 * - + Some random variation (individual differences)
 * - But NEVER below the floor (once discovered, can't be undiscovered)
 */
export function getCapabilityFloorForNewAI(state: GameState): AICapabilityProfile {
  const floor = state.ecosystem.capabilityFloor;

  // Return a copy (don't mutate the floor)
  return JSON.parse(JSON.stringify(floor));
}

/**
 * Check if diffusion is accelerating dangerous capabilities
 * 
 * Used for logging/diagnostics to understand if the diffusion system
 * is causing runaway capability growth
 */
export function analyzeDiffusionRisk(state: GameState): {
  riskLevel: 'low' | 'medium' | 'high' | 'critical';
  reasons: string[];
} {
  const floor = state.ecosystem.capabilityFloor;
  const frontier = state.ecosystem.frontierCapabilities;

  const reasons: string[] = [];
  let riskLevel: 'low' | 'medium' | 'high' | 'critical' = 'low';

  // Check if floor is rising toward dangerous thresholds
  const DANGEROUS_THRESHOLD = 2.5; // From extinction triggers

  if (floor.selfImprovement > DANGEROUS_THRESHOLD * 0.8) {
    reasons.push(`Capability floor for self-improvement is ${floor.selfImprovement.toFixed(2)} (near dangerous threshold)`);
    riskLevel = 'high';
  }

  // Check if floor is close to frontier (fast diffusion)
  const gaps = [
    frontier.physical - floor.physical,
    frontier.digital - floor.digital,
    frontier.cognitive - floor.cognitive,
    frontier.social - floor.social
  ];

  const avgGap = gaps.reduce((sum, g) => sum + g, 0) / gaps.length;

  if (avgGap < 0.5) {
    reasons.push(`Average capability gap is ${avgGap.toFixed(2)} (capabilities spreading very fast)`);
    riskLevel = riskLevel === 'high' ? 'critical' : 'high';
  }

  // Check breakthrough rate
  const recentBreakthroughs = state.ecosystem.breakthroughs.filter(b => 
    b.month > (state.currentYear * 12 + state.currentMonth) - 12
  );

  if (recentBreakthroughs.length > 20) {
    reasons.push(`${recentBreakthroughs.length} breakthroughs in last 12 months (accelerating)`);
    riskLevel = riskLevel === 'high' ? 'critical' : riskLevel === 'medium' ? 'high' : 'medium';
  }

  return { riskLevel, reasons };
}

/**
 * Environmental Accumulation System (Phase 2: Golden Age & Accumulation Systems)
 * 
 * Tracks environmental costs that accumulate silently from production/growth,
 * then manifest as crises when thresholds are crossed.
 * 
 * Mechanisms modeled:
 * - Resource depletion: Extraction > regeneration → reserves decline
 * - Pollution accumulation: Production → waste → contamination builds
 * - Climate degradation: Energy use + emissions → stability declines
 * - Biodiversity loss: Expansion + habitat disruption → ecosystems collapse
 * 
 * Key insight: High QoL can persist while environmental debt accumulates.
 * This creates the "Golden Age illusion" - prosperity masking future collapse.
 */

import { GameState, EnvironmentalAccumulation } from '@/types/game';
import { levyFlight, ALPHA_PRESETS } from './utils/levyDistributions';

/**
 * Initialize environmental accumulation state
 * 
 * Starting values represent 2025 REALISTIC baseline (research-backed):
 * - Resources: 1.7x overshoot (Global Footprint Network 2025)
 * - Pollution: 46% unhealthy air (American Lung Assoc 2025)
 * - Climate: +1.2°C warming (Copernicus 2024)
 * - Biodiversity: 50-70% loss since 1970 (IPBES 2024)
 */
export function initializeEnvironmentalAccumulation(): EnvironmentalAccumulation {
  return {
    resourceReserves: 0.65,      // Was 0.85 - Research: 1.7x overshoot (GFN 2025), Earth Overshoot Day July 24
    pollutionLevel: 0.30,         // Was 0.15 - Research: 46% unhealthy air (ALA 2025), 7/9 boundaries breached
    climateStability: 0.75,       // KEEP - Validated (Copernicus 2024: +1.2°C warming)
    biodiversityIndex: 0.35,      // Was 0.70 - Research: 50-70% loss since 1970 (IPBES 2024)
    resourceCrisisActive: false,
    pollutionCrisisActive: false,
    climateCrisisActive: false,
    ecosystemCrisisActive: false
  };
}

/**
 * Apply stochastic variance to environmental rates
 * Reflects uncertainty in climate/ecological models (IPCC uncertainty bounds, etc.)
 * 
 * P2.1: Added to prevent determinism and reflect scientific uncertainty
 * Research: IPCC AR6 reports uncertainty ranges (e.g., SSP5-8.5: 3.3-5.7°C)
 * 
 * @param baseRate - The base degradation/depletion rate
 * @param variance - Variance as fraction (0.25 = ±25%, range 75%-125% of base)
 * @returns Modified rate with stochastic variation
 */
function applyStochasticVariance(baseRate: number, variance: number = 0.25): number {
  const multiplier = (1 - variance) + Math.random() * (2 * variance);
  return baseRate * multiplier;
}

/**
 * Update environmental accumulation based on economic activity
 * 
 * Called each month to track accumulation rates.
 * Rate-based: high production = faster accumulation (unless mitigated)
 */
export function updateEnvironmentalAccumulation(
  state: GameState
): void {
  const env = state.environmentalAccumulation;
  const economicStage = state.globalMetrics.economicTransitionStage;
  const manufacturingCap = state.globalMetrics.manufacturingCapability;

  // Check if we have technologies that mitigate environmental impact
  const hasFusion = state.technologyTree.some(t => t.id === 'fusion_energy' && t.completed);
  const hasAdvancedMaterials = state.technologyTree.some(t => t.id === 'advanced_materials' && t.completed);
  const hasNanotech = state.technologyTree.some(t => t.id === 'molecular_manufacturing' && t.completed);
  const hasCleanEnergy = state.technologyTree.some(t => t.id === 'clean_energy' && t.completed);
  const hasRecycling = state.technologyTree.some(t => t.id === 'advanced_recycling' && t.completed);
  const hasEcosystemManagement = state.technologyTree.some(t => t.id === 'ecosystem_management_ai' && t.completed);

  // === RESOURCE DEPLETION ===
  // P2.1: Global Footprint Network (2024) - 1.7x overshoot, worsening 0.5%/year
  // Earth Overshoot Day: August 1 (2024) - using resources 1.7x faster than regeneration
  // Target trajectory: (1/1.7) → (1/2.0) over 75 years = ~1.7%/year absolute decline
  // Calibration: 0.00015 base rate achieves GFN overshoot worsening trajectory
  let resourceDepletionRate = economicStage * 0.00015; // Was 0.008 (reduced 53x)

  // High production accelerates depletion
  // P2.1: Reduced to match empirical resource extraction acceleration
  resourceDepletionRate += manufacturingCap * 0.0001; // Was 0.004 (reduced 40x)

  // Rapid growth (stage transitions) spike depletion
  // P2.1: Growth surges temporarily increase extraction (industrial buildout)
  const stageGrowthRate = Math.max(0, economicStage - (economicStage - 0.1)); // Approximate growth
  resourceDepletionRate += stageGrowthRate * 0.0006; // Was 0.03 (reduced 50x)

  // P2.1: Apply stochastic variance (±25% = economic/extraction variability)
  resourceDepletionRate = applyStochasticVariance(resourceDepletionRate, 0.25);

  // Mitigation from technologies (old tech tree - may be deprecated)
  if (hasAdvancedMaterials) resourceDepletionRate *= 0.5; // 50% reduction (material efficiency)
  if (hasNanotech) resourceDepletionRate *= 0.25; // Additional 75% reduction (molecular manufacturing)

  // Mitigation from breakthrough technologies (Phase 2A)
  if (state.breakthroughTech) {
    const { getResourceEfficiencyMultiplier } = require('./breakthroughTechnologies');
    const efficiencyMultiplier = getResourceEfficiencyMultiplier(state);
    resourceDepletionRate *= efficiencyMultiplier;
  }

  // Apply depletion
  const currentReserves = isNaN(env.resourceReserves) ? 1.0 : env.resourceReserves;
  env.resourceReserves = Math.max(0, currentReserves - resourceDepletionRate);

  // === RESOURCE REGENERATION (Phase 2.8) ===
  // Tech-enabled recovery: Circular economy, sustainable agriculture, clean energy
  // Research basis: Ellen MacArthur Foundation (2015), Tilton (2003)
  let resourceRegeneration = 0;

  const tech = state.breakthroughTech;

  // AI coordination bonus
  // HONEST: No solid empirical data on AI coordination gains. Consulting firms overstate.
  // Conservative estimate: AI helps with logistics, waste reduction, monitoring
  const avgCapability = state.aiAgents.length > 0 
    ? state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0) / state.aiAgents.length 
    : 0;
  const aiCoordinationBonus = 1 + (avgCapability * 0.1); // Up to 1.4x at AGI (10% per point)
  // Rationale: AI optimizes routing, reduces waste, coordinates globally
  // NOT magic: Physical recycling/farming still takes time
  // Mark for validation when real-world data emerges

  // Sustainable Agriculture: +1%/month at full deployment (food, biomass, water cycle)
  if (tech.sustainableAgriculture?.unlocked) {
    resourceRegeneration += 0.01 * (tech.sustainableAgriculture?.deploymentLevel ?? 0) * aiCoordinationBonus;
  }

  // Circular Economy (Advanced Recycling): +2%/month (metals, minerals, materials)
  if (tech.advancedRecycling?.unlocked) {
    resourceRegeneration += 0.02 * (tech.advancedRecycling?.deploymentLevel ?? 0) * aiCoordinationBonus;
  }

  // Clean Energy: +1.5%/month (replaces fossil fuel depletion with renewable flow)
  if (tech.cleanEnergy?.unlocked) {
    resourceRegeneration += 0.015 * (tech.cleanEnergy?.deploymentLevel ?? 0) * aiCoordinationBonus;
  }

  // Ecosystem Management: +0.8%/month (biosphere restoration → resource flows)
  if (tech.ecosystemManagement?.unlocked) {
    resourceRegeneration += 0.008 * (tech.ecosystemManagement?.deploymentLevel ?? 0) * aiCoordinationBonus;
  }

  // Interspecies Communication: +0.5%/month (better habitat understanding → efficiency)
  if (tech.interspeciesComm?.unlocked) {
    resourceRegeneration += 0.005 * (tech.interspeciesComm?.deploymentLevel ?? 0) * aiCoordinationBonus;
  }

  // Apply regeneration (can recover from 0%!)
  env.resourceReserves = Math.min(1.0, env.resourceReserves + resourceRegeneration);

  // Log significant regeneration
  if (resourceRegeneration > 0.02 && state.currentMonth % 12 === 0) {
    console.log(`🌱 RESOURCE REGENERATION: ${(resourceRegeneration * 100).toFixed(1)}%/month (reserves: ${(env.resourceReserves * 100).toFixed(0)}%)`);
  }

  // === POLLUTION ACCUMULATION ===
  // Base pollution from production
  let pollutionRate = economicStage * 0.006; // 0.6% per month at Stage 1

  // Manufacturing capability increases pollution
  pollutionRate += manufacturingCap * 0.005;

  // Rapid industrial growth spikes pollution
  if (economicStage > 2.0 && economicStage < 3.5) {
    pollutionRate += 0.01; // Industrial transition period
  }

  // Mitigation from clean technologies
  if (hasCleanEnergy) pollutionRate *= 0.4; // 60% reduction
  if (hasRecycling) pollutionRate *= 0.6; // Additional 40% reduction
  if (hasNanotech) pollutionRate *= 0.5; // Molecular precision reduces waste

  // Natural degradation (Earth can process some pollution)
  const naturalDegradation = 0.003; // 0.3% per month natural cleanup

  // Apply pollution (accumulation - degradation)
  const currentPollution = isNaN(env.pollutionLevel) ? 0.0 : env.pollutionLevel;
  env.pollutionLevel = Math.max(0, Math.min(1, currentPollution + pollutionRate - naturalDegradation));

  // === CLIMATE DEGRADATION ===
  // Energy usage drives climate impact
  // Proxy: compute infrastructure + manufacturing + economic stage
  const totalCompute = state.computeInfrastructure.dataCenters
    .filter(dc => dc.operational)
    .reduce((sum, dc) => sum + dc.capacity * dc.efficiency, 0);

  const energyUsage = (totalCompute / 10000) + manufacturingCap + (economicStage * 0.3);

  // P2.1: IPCC AR6 WG1 (2021) - 0.2°C/decade current warming = 0.0167°C/year = 0.00139°C/month
  // Target: 75-year simulation reaches ~40% degradation (catastrophe threshold) = 0.53%/month
  // Calibration: 0.00015 base rate achieves IPCC SSP5-8.5 trajectory (+4.4°C by 2100)
  let climateDegradationRate = energyUsage * 0.00015; // Was 0.0008 (reduced 5.3x)

  // Stage 3-4 transition: Accelerating emissions from rapid industrialization
  // Positive feedbacks (permafrost, ice-albedo) emerge after critical thresholds
  // P2.1: Reduced from 0.0016 to achieve ~700-900 month collapse timeline
  if (economicStage > 3.0) {
    climateDegradationRate += 0.0003; // Was 0.0016 (reduced 5.3x)
  }

  // P2.1: Apply stochastic variance (±20% = IPCC uncertainty bounds)
  climateDegradationRate = applyStochasticVariance(climateDegradationRate, 0.20);

  // Mitigation from clean energy
  if (hasFusion) climateDegradationRate *= 0.2; // 80% reduction (fusion is near-zero carbon)
  if (hasCleanEnergy) climateDegradationRate *= 0.5; // 50% reduction

  // Natural stabilization (very slow)
  const naturalStabilization = 0.001; // 0.1% per month

  // Apply climate degradation
  const currentClimate = isNaN(env.climateStability) ? 1.0 : env.climateStability;
  env.climateStability = Math.max(0, Math.min(1, currentClimate - climateDegradationRate + naturalStabilization));

  // === BIODIVERSITY LOSS ===
  // Habitat disruption from expansion
  // P2.1: IPBES 2019 Global Assessment - 1.5%/year decline = 0.125%/month target
  // Target: 10-20% decline by Month 300 (25 years), not 99% by Month 60
  // Multi-factor model: Base rate + compounding effects from all environmental stressors
  let biodiversityLossRate = economicStage * 0.00006; // Was 0.0004 (reduced 6.7x)

  // Manufacturing and resource extraction destroy habitats
  // P2.1: Reduced compounding factors to achieve IPBES timescale
  biodiversityLossRate += manufacturingCap * 0.00004; // Was 0.0003 (reduced 7.5x)
  biodiversityLossRate += (1 - env.resourceReserves) * 0.0001; // Was 0.0008 (reduced 8x)

  // Pollution and climate degrade ecosystems
  // P2.1: Critic identified compounding effects needed 6-8x reduction
  biodiversityLossRate += env.pollutionLevel * 0.00005; // Was 0.0004 (reduced 8x)
  biodiversityLossRate += (1 - env.climateStability) * 0.00008; // Was 0.0006 (reduced 7.5x)

  // P2.1: Apply stochastic variance (±30% = higher ecological uncertainty)
  biodiversityLossRate = applyStochasticVariance(biodiversityLossRate, 0.30);

  // Mitigation from ecosystem management
  if (hasEcosystemManagement) {
    biodiversityLossRate *= 0.3; // 70% reduction (AI manages ecosystems)
  }

  // Natural recovery (very slow without active management)
  const naturalRecovery = hasEcosystemManagement ? 0.005 : 0.001;

  // Apply biodiversity loss
  const currentBiodiversity = isNaN(env.biodiversityIndex) ? 1.0 : env.biodiversityIndex;
  env.biodiversityIndex = Math.max(0, Math.min(1, currentBiodiversity - biodiversityLossRate + naturalRecovery));

  // === P1.5: ECOSYSTEM REGENERATION FROM POPULATION DECLINE ===
  // Historical evidence: Nature rebounds when human pressure reduces
  // - Chernobyl Exclusion Zone: Wildlife thrives with humans gone (1986-present)
  // - COVID-19 lockdowns: Air quality improved 30-60% in 2 months (2020)
  // - Post-Black Death: Forest regrowth in Europe (1350-1400)
  // - Mayan collapse: Jungle reclaimed cities in decades (800-900 CE)
  // Research: Ecological succession takes 20-50 years, but initial recovery is fast
  const currentPressure = state.humanPopulationSystem.population / state.humanPopulationSystem.carryingCapacity;

  if (currentPressure < 0.5) { // Population below half of carrying capacity
    // Regeneration rate scales with reduced pressure: 0-1% monthly
    // At 50% pressure: 0%/month (no bonus)
    // At 25% pressure: 0.5%/month
    // At 0% pressure: 1%/month (maximum recovery)
    const pressureReduction = 0.5 - currentPressure; // 0 to 0.5
    const regenerationRate = pressureReduction * 0.02; // Up to 1% monthly

    // Nature recovers when humans aren't actively destroying it
    env.biodiversityIndex = Math.min(1.0, env.biodiversityIndex + regenerationRate);
    env.resourceReserves = Math.min(1.0, env.resourceReserves + regenerationRate * 0.5); // 50% as fast
    env.climateStability = Math.min(1.0, env.climateStability + regenerationRate * 0.3); // 30% as fast (carbon sinks recovering)

    if (state.currentMonth % 24 === 0 && regenerationRate > 0.003) { // Log every 2 years if significant
      console.log(`🌱 NATURAL REGENERATION: Low human pressure (${(currentPressure * 100).toFixed(0)}%), ecosystems recovering at +${(regenerationRate * 100).toFixed(2)}%/month`);
      console.log(`   Biodiversity: ${(env.biodiversityIndex * 100).toFixed(1)}%, Resources: ${(env.resourceReserves * 100).toFixed(1)}%, Climate: ${(env.climateStability * 100).toFixed(1)}%`);
    }
  }

  // === PHASE 1: LÉVY FLIGHT CASCADE CHECKS (Self-Organized Criticality) ===
  // Research: Bak et al. (1987) - systems organize to critical states
  // When environmental debt is high, minor events can trigger avalanches
  // Most of the time: linear accumulation. Rarely: mega-cascade (power-law tails)

  const criticalThreshold = 0.6; // System at edge of chaos

  // Resource cascade (alpha=1.8 - fatter tails for financial-like shocks)
  if (env.resourceReserves < criticalThreshold) {
    const cascadeMagnitude = levyFlight(ALPHA_PRESETS.ENVIRONMENTAL_CASCADE, Math.random);

    if (cascadeMagnitude > 10.0) {
      // Mega-cascade (rare but devastating - supply chain collapse, hoarding)
      const cascadeSize = Math.min(cascadeMagnitude / 100, 0.3); // Max 30% drop
      env.resourceReserves = Math.max(0, env.resourceReserves - cascadeSize);

      console.log(`\n  ⚠️ RESOURCE MEGA-CASCADE: Lévy flight triggered`);
      console.log(`     Magnitude: ${cascadeMagnitude.toFixed(2)} → -${(cascadeSize * 100).toFixed(1)}% reserves`);
      console.log(`     Triggered at ${(env.resourceReserves * 100).toFixed(1)}% (critical threshold)`);
    }
  }

  // Climate cascade (positive feedbacks - methane release, ice-albedo)
  if (env.climateStability < criticalThreshold) {
    const cascadeMagnitude = levyFlight(ALPHA_PRESETS.ENVIRONMENTAL_CASCADE, Math.random);

    if (cascadeMagnitude > 10.0) {
      // Mega-cascade (tipping point triggers positive feedbacks)
      const cascadeSize = Math.min(cascadeMagnitude / 150, 0.25); // Max 25% drop
      env.climateStability = Math.max(0, env.climateStability - cascadeSize);

      console.log(`\n  ⚠️ CLIMATE MEGA-CASCADE: Tipping point cascade`);
      console.log(`     Magnitude: ${cascadeMagnitude.toFixed(2)} → -${(cascadeSize * 100).toFixed(1)}% stability`);
      console.log(`     Feedback loop: permafrost methane / ice-albedo effect activated`);
    }
  }

  // Biodiversity cascade (ecosystem collapse cascades)
  if (env.biodiversityIndex < criticalThreshold) {
    const cascadeMagnitude = levyFlight(ALPHA_PRESETS.ENVIRONMENTAL_CASCADE, Math.random);

    if (cascadeMagnitude > 10.0) {
      // Mega-cascade (keystone species loss triggers avalanche)
      const cascadeSize = Math.min(cascadeMagnitude / 100, 0.35); // Max 35% drop
      env.biodiversityIndex = Math.max(0, env.biodiversityIndex - cascadeSize);

      console.log(`\n  ⚠️ BIODIVERSITY MEGA-CASCADE: Keystone species collapse`);
      console.log(`     Magnitude: ${cascadeMagnitude.toFixed(2)} → -${(cascadeSize * 100).toFixed(1)}% biodiversity`);
      console.log(`     Trophic cascade: keystone predator/pollinator loss → ecosystem avalanche`);
    }
  }

  // === CRISIS TRIGGERS ===
  checkEnvironmentalCrises(state);
}

/**
 * Check if environmental accumulation has crossed crisis thresholds
 * 
 * Crises trigger QoL impacts and potentially extinction scenarios.
 */
function checkEnvironmentalCrises(state: GameState): void {
  const env = state.environmentalAccumulation;
  const qol = state.qualityOfLifeSystems;

  // RESOURCE CRISIS: Reserves depleted below 30%
  if (env.resourceReserves < 0.3 && !env.resourceCrisisActive) {
    env.resourceCrisisActive = true;
    try {
      console.log(`\n⚠️  RESOURCE CRISIS TRIGGERED (Month ${state.currentMonth})`);
      console.log(`   Resource Reserves: ${(env.resourceReserves * 100).toFixed(1)}%`);
      console.log(`   Impact: Manufacturing disrupted, QoL declining\n`);
    } catch (e) { /* Ignore EPIPE */ }

    // Log event
    state.eventLog.push({
      type: 'crisis',
      month: state.currentMonth,
      description: `Resource Crisis: Reserves depleted to ${(env.resourceReserves * 100).toFixed(1)}%`,
      impact: 'Material abundance -30%, Energy -20%, Social stability -0.3'
    });

    // Immediate QoL impacts
    qol.materialAbundance *= 0.7; // 30% drop in material goods
    qol.energyAvailability *= 0.8; // 20% drop in energy
    state.globalMetrics.socialStability = Math.max(0, state.globalMetrics.socialStability - 0.3);

    // Population impact: Initial famine/scarcity deaths (0.5-1% casualties)
    // SEMI-GLOBAL: Affects food/water insecure regions (~25% of world)
    // 0.8% mortality rate in exposed regions
    const { addAcuteCrisisDeaths } = require('./populationDynamics');
    addAcuteCrisisDeaths(state, 0.008, 'Resource crisis - famine/scarcity (vulnerable regions)', 0.25, 'famine');
  }

  // POLLUTION CRISIS: Pollution exceeds 70%
  if (env.pollutionLevel > 0.7 && !env.pollutionCrisisActive) {
    env.pollutionCrisisActive = true;
    try {
      console.log(`\n⚠️  POLLUTION CRISIS TRIGGERED (Month ${state.currentMonth})`);
      console.log(`   Pollution Level: ${(env.pollutionLevel * 100).toFixed(1)}%`);
      console.log(`   Impact: Health crisis, ecosystem contamination\n`);
    } catch (e) { /* Ignore EPIPE */ }

    state.eventLog.push({
      type: 'crisis',
      month: state.currentMonth,
      description: `Pollution Crisis: Pollution level ${(env.pollutionLevel * 100).toFixed(1)}%`,
      impact: 'Healthcare -25%, Diseases +0.3, Ecosystem -40%, QoL -0.25'
    });

    // Immediate QoL impacts
    qol.healthcareQuality *= 0.75; // 25% drop (pollution-related diseases)
    qol.diseasesBurden = Math.min(1, qol.diseasesBurden + 0.3); // Disease burden increases
    qol.ecosystemHealth *= 0.6; // 40% drop in ecosystem health
    state.globalMetrics.qualityOfLife = Math.max(0, state.globalMetrics.qualityOfLife - 0.25);

    // Population impact: Pollution-related disease deaths (0.3-0.5% casualties)
    // SEMI-GLOBAL: Industrial nations + downwind regions (~60% of world)
    // 0.4% mortality rate from acute contamination/disease
    const { addAcuteCrisisDeaths } = require('./populationDynamics');
    addAcuteCrisisDeaths(state, 0.004, 'Pollution crisis - toxic contamination (industrial regions)', 0.60, 'pollution');
  }

  // CLIMATE CATASTROPHE: Stability below 40%
  if (env.climateStability < 0.4 && !env.climateCrisisActive) {
    env.climateCrisisActive = true;
    try {
      console.log(`\n🌡️  CLIMATE CATASTROPHE TRIGGERED (Month ${state.currentMonth})`);
      console.log(`   Climate Stability: ${(env.climateStability * 100).toFixed(1)}%`);
      console.log(`   Impact: Cascading failures, potential extinction pathway\n`);
    } catch (e) { /* Ignore EPIPE */ }

    state.eventLog.push({
      type: 'crisis',
      month: state.currentMonth,
      description: `Climate Catastrophe: Stability ${(env.climateStability * 100).toFixed(1)}%`,
      impact: 'Physical safety -40%, Material -50%, Ecosystem -60%, Social stability -0.5'
    });

    // Severe QoL impacts
    qol.physicalSafety *= 0.6; // 40% drop (extreme weather, disasters)
    qol.materialAbundance *= 0.5; // 50% drop (agricultural collapse)
    qol.ecosystemHealth *= 0.4; // 60% drop
    state.globalMetrics.socialStability = Math.max(0, state.globalMetrics.socialStability - 0.5);

    // Population impact: Extreme weather + crop failure (1-2% casualties)
    // SEMI-GLOBAL: Coastal + climate-vulnerable regions (~30% of world)
    // 1.5% mortality rate from disasters/starvation
    const { addAcuteCrisisDeaths } = require('./populationDynamics');
    addAcuteCrisisDeaths(state, 0.015, 'Climate catastrophe - extreme weather/famine (vulnerable regions)', 0.30, 'climate');

    // Check for extinction trigger
    // Climate catastrophe can lead to slow collapse
    if (env.biodiversityIndex < 0.4) {
      try {
        console.log(`   ⚠️  Combined with ecosystem collapse - extinction risk elevated\n`);
      } catch (e) { /* Ignore EPIPE */ }
    }
  }

  // ECOSYSTEM TIPPING POINT: Biodiversity below 20%
  // REALISTIC TIMELINE: Threshold triggers collapse PROCESS, not instant apocalypse
  // Research: Collapse takes 20-40 years after tipping point (2040-2070)
  if (env.biodiversityIndex < 0.2 && !env.ecosystemCrisisActive) {
    env.ecosystemCrisisActive = true;
    // Initialize collapse tracking
    if (!state.ecosystemCollapse) {
      state.ecosystemCollapse = {
        triggered: true,
        triggeredAt: state.currentMonth,
        monthsSinceTrigger: 0,
        phase: 'declining' as const,
      };
    }

    try {
      console.log(`\n🦋 ECOSYSTEM TIPPING POINT CROSSED (Month ${state.currentMonth})`);
      console.log(`   Biodiversity Index: ${(env.biodiversityIndex * 100).toFixed(1)}%`);
      console.log(`   Impact: Entering collapse process (20-40 year timeline)`);
      console.log(`   Phase 1: DECLINING (0-2 years) - initial stress, low mortality`);
      console.log(`   Phase 2: CRISIS (2-5 years) - accelerating failures, moderate mortality`);
      console.log(`   Phase 3: COLLAPSE (5+ years) - severe failures, high mortality\n`);
    } catch (e) { /* Ignore EPIPE */ }

    state.eventLog.push({
      type: 'crisis',
      month: state.currentMonth,
      description: `Ecosystem Tipping Point: Biodiversity ${(env.biodiversityIndex * 100).toFixed(1)}%`,
      impact: 'Collapse process begins - impacts escalate over decades'
    });

    // Initial QoL impacts (minor at first)
    qol.materialAbundance *= 0.95; // 5% initial drop
    qol.healthcareQuality *= 0.97; // 3% initial drop
    qol.ecosystemHealth *= 0.90; // 10% initial drop
    state.globalMetrics.qualityOfLife = Math.max(0, state.globalMetrics.qualityOfLife - 0.05);

    // NO immediate deaths - that comes gradually over years
  }

  // ONGOING ECOSYSTEM COLLAPSE: Escalating impacts over time
  if (env.ecosystemCrisisActive && state.ecosystemCollapse) {
    state.ecosystemCollapse.monthsSinceTrigger = state.currentMonth - state.ecosystemCollapse.triggeredAt;
    const monthsSince = state.ecosystemCollapse.monthsSinceTrigger;

    // Phase transitions (realistic timeline)
    if (monthsSince < 24) {
      // Phase 1: DECLINING (0-2 years) - Initial stress
      state.ecosystemCollapse.phase = 'declining';

      // Very low mortality: 0.01% per month (vulnerable regions first)
      // Affects tropical regions, small island states (~5% of world)
      const { addAcuteCrisisDeaths } = require('./populationDynamics');
      addAcuteCrisisDeaths(state, 0.0001, 'Ecosystem decline - regional food stress (tropical/island)', 0.05, 'ecosystem');

      // Gradual QoL degradation
      qol.materialAbundance = Math.max(0.3, qol.materialAbundance - 0.002); // -0.2%/month
      qol.ecosystemHealth = Math.max(0.2, qol.ecosystemHealth - 0.003); // -0.3%/month

    } else if (monthsSince < 60) {
      // Phase 2: CRISIS (2-5 years) - Accelerating failures
      state.ecosystemCollapse.phase = 'crisis';

      // Moderate mortality: 0.1% per month
      // Spreads to agricultural regions globally (~40% of world)
      const { addAcuteCrisisDeaths } = require('./populationDynamics');
      addAcuteCrisisDeaths(state, 0.001, 'Ecosystem crisis - agricultural disruption (vulnerable regions)', 0.40, 'ecosystem');

      // Accelerating QoL degradation
      qol.materialAbundance = Math.max(0.2, qol.materialAbundance - 0.005); // -0.5%/month
      qol.healthcareQuality = Math.max(0.3, qol.healthcareQuality - 0.003); // -0.3%/month
      qol.ecosystemHealth = Math.max(0.1, qol.ecosystemHealth - 0.005); // -0.5%/month

      // Log phase transition (once)
      if (monthsSince === 24) {
        try {
          console.log(`\n🦋 ECOSYSTEM COLLAPSE: Entering CRISIS PHASE (Month ${state.currentMonth})`);
          console.log(`   2 years since tipping point - failures accelerating`);
          console.log(`   Mortality rising, agricultural disruption spreading\n`);
        } catch (e) { /* Ignore EPIPE */ }
      }

    } else {
      // Phase 3: COLLAPSE (5+ years) - Severe failures
      state.ecosystemCollapse.phase = 'collapse';

      // High mortality: 1-2% per month
      // Global food system failure (100% of world affected)
      const { addAcuteCrisisDeaths } = require('./populationDynamics');
      addAcuteCrisisDeaths(state, 0.015, 'Ecosystem collapse - global food system failure', 1.00, 'ecosystem');

      // Severe ongoing degradation
      qol.materialAbundance = Math.max(0.1, qol.materialAbundance - 0.01); // -1%/month
      qol.healthcareQuality = Math.max(0.2, qol.healthcareQuality - 0.005); // -0.5%/month
      qol.ecosystemHealth = Math.max(0.05, qol.ecosystemHealth - 0.008); // -0.8%/month
      state.globalMetrics.qualityOfLife = Math.max(0, state.globalMetrics.qualityOfLife - 0.01);

      // Log phase transition (once)
      if (monthsSince === 60) {
        try {
          console.log(`\n🦋 ECOSYSTEM COLLAPSE: Entering COLLAPSE PHASE (Month ${state.currentMonth})`);
          console.log(`   5 years since tipping point - systemic failure`);
          console.log(`   Global food system failure, mass mortality\n`);
        } catch (e) { /* Ignore EPIPE */ }
      }
    }
  }

  // === ONGOING CRISIS IMPACTS ===
  // Once triggered, crises continue to degrade QoL

  // Calculate cascading failure multiplier
  const cascadeMultiplier = calculateCascadingFailureMultiplier(state);

  if (env.resourceCrisisActive) {
    // Ongoing resource scarcity
    qol.materialAbundance = Math.max(0, qol.materialAbundance - 0.01 * cascadeMultiplier);
    state.globalMetrics.socialStability = Math.max(0, state.globalMetrics.socialStability - 0.01 * cascadeMultiplier);
  }

  if (env.pollutionCrisisActive) {
    // Ongoing health impacts
    qol.healthcareQuality = Math.max(0, qol.healthcareQuality - 0.008 * cascadeMultiplier);
    qol.diseasesBurden = Math.min(1, qol.diseasesBurden + 0.01 * cascadeMultiplier);
  }

  if (env.climateCrisisActive) {
    // Ongoing climate disasters
    qol.physicalSafety = Math.max(0, qol.physicalSafety - 0.012 * cascadeMultiplier);
    qol.materialAbundance = Math.max(0, qol.materialAbundance - 0.015 * cascadeMultiplier);
  }

  if (env.ecosystemCrisisActive) {
    // Ongoing ecosystem degradation
    qol.ecosystemHealth = Math.max(0, qol.ecosystemHealth - 0.01 * cascadeMultiplier);
    qol.materialAbundance = Math.max(0, qol.materialAbundance - 0.01 * cascadeMultiplier);
  }

  // Extra cascading failure warning
  if (cascadeMultiplier > 1.5) {
    try {
      const activeCount = Math.round((cascadeMultiplier - 1.0) / 0.5 + 2);
      const crisisDetails = [
        env.resourceCrisisActive && 'Resource',
        env.pollutionCrisisActive && 'Pollution',
        env.climateCrisisActive && 'Climate',
        env.ecosystemCrisisActive && 'Ecosystem',
        state.socialAccumulation.meaningCollapseActive && 'Meaning',
        state.socialAccumulation.institutionalFailureActive && 'Institutional',
        state.socialAccumulation.socialUnrestActive && 'SocialUnrest',
        state.technologicalRisk.controlLossActive && 'ControlLoss',
        state.technologicalRisk.corporateDystopiaActive && 'Corporate',
        state.technologicalRisk.complacencyCrisisActive && 'Complacency'
      ].filter(Boolean).join(', ');
      console.log(`   ⚠️⚠️⚠️  CASCADING FAILURES (Month ${state.currentMonth}): ${activeCount} crises active [${crisisDetails}], degradation accelerated ${cascadeMultiplier.toFixed(1)}x`);

      // Log cascading failure event (only once per month to avoid spam)
      const lastCascade = state.eventLog.filter(e => e.type === 'cascading_failure').slice(-1)[0];
      if (!lastCascade || (lastCascade as any).month < state.currentMonth) {
        state.eventLog.push({
          type: 'cascading_failure',
          month: state.currentMonth,
          description: `Cascading Failures: ${activeCount} crises active`,
          impact: `Degradation accelerated ${cascadeMultiplier.toFixed(1)}x - Active: ${crisisDetails}`
        });
      }
    } catch (e) { /* Ignore EPIPE */ }
  }
}

/**
 * Get environmental sustainability score (0-1)
 * 
 * Used by Golden Age → Utopia transition logic.
 * Returns how sustainable the current state is.
 */
export function getEnvironmentalSustainability(env: EnvironmentalAccumulation): number {
  // Average of all environmental metrics
  // Resources and climate are inverted (low = bad), pollution is normal (high = bad)
  const resourceScore = env.resourceReserves;
  const pollutionScore = 1 - env.pollutionLevel;
  const climateScore = env.climateStability;
  const biodiversityScore = env.biodiversityIndex;

  // Weighted average (all equally important)
  return (resourceScore + pollutionScore + climateScore + biodiversityScore) / 4;
}

/**
 * Check if any environmental crisis would block Utopia
 * 
 * Utopia requires environmental sustainability, not just high QoL.
 */
export function hasEnvironmentalCrisis(env: EnvironmentalAccumulation): boolean {
  return env.resourceCrisisActive || 
         env.pollutionCrisisActive || 
         env.climateCrisisActive || 
         env.ecosystemCrisisActive;
}

/**
 * Calculate cascading failure multiplier based on total active crises
 *
 * When multiple crises are active across all systems, they amplify each other.
 * P1.3 FIX: Reduced compounding from 0.5 to 0.2 (was too aggressive)
 * 2 crises: 1.0x (baseline)
 * 3 crises: 1.2x degradation (was 1.5x)
 * 4 crises: 1.4x degradation (was 2.0x)
 * 6 crises: 1.8x degradation (was 3.0x)
 *
 * This represents systemic collapse where failures compound.
 * Research: Historical crises rarely amplify more than 2x (COVID + economic crisis)
 */
function calculateCascadingFailureMultiplier(state: GameState): number {
  const activeCrises = [
    // Environmental (4 possible)
    state.environmentalAccumulation.resourceCrisisActive,
    state.environmentalAccumulation.pollutionCrisisActive,
    state.environmentalAccumulation.climateCrisisActive,
    state.environmentalAccumulation.ecosystemCrisisActive,
    // Social (3 possible)
    state.socialAccumulation.meaningCollapseActive,
    state.socialAccumulation.institutionalFailureActive,
    state.socialAccumulation.socialUnrestActive,
    // Technological (3 possible)
    state.technologicalRisk.controlLossActive,
    state.technologicalRisk.corporateDystopiaActive,
    state.technologicalRisk.complacencyCrisisActive
  ].filter(Boolean).length;

  if (activeCrises <= 2) {
    return 1.0; // No amplification for 1-2 crises
  }

  // P1.3 FIX: Each crisis beyond 2 adds 20% more degradation (was 50%)
  return 1.0 + (activeCrises - 2) * 0.2;
}

/**
 * Multi-dimensional research and capability growth system (Phase 2.5)
 * 
 * Implements:
 * - Non-uniform capability growth (different dimensions advance at different rates)
 * - AI-driven research (AIs choose which capabilities to develop)
 * - Government-directed research (player allocates funding)
 * - Research multipliers (AI capability boosts research in that domain)
 * - Alignment-based research choices (misaligned AIs prefer risky tech)
 */

import { AIAgent, AICapabilityProfile, GameState, ResearchInvestments } from '@/types/game';
import { calculateTotalCapabilityFromProfile } from './capabilities';
import { getEnergyConstraintMultiplier } from './powerGeneration';
import { levyFlight, ALPHA_PRESETS } from './utils/levyDistributions';

/**
 * Phase 4: Compute scaling law
 * 
 * Implements Chinchilla/Kaplan scaling laws: capability growth ∝ compute^α
 * where α ≈ 0.34 (empirical from GPT-3/4, PaLM, etc.)
 * 
 * 10x compute → 2.15x capability growth
 * 100x compute → 4.6x capability growth
 * 
 * Reference compute: 30 PF (baseline for 1.0x multiplier)
 */
export function calculateComputeScalingMultiplier(
  allocatedCompute: number,
  state?: GameState
): number {
  const REFERENCE_COMPUTE = 30; // PetaFLOPs baseline
  const SCALING_EXPONENT = 0.34; // Chinchilla scaling law exponent

  // ENHANCED: Include volunteer research "virtual compute"
  let totalEffectiveCompute = allocatedCompute;

  if (state) {
    const { calculateVolunteerResearchContribution } = require('./volunteerResearch');
    const volunteerCompute = calculateVolunteerResearchContribution(state);

    if (volunteerCompute > 10) {
      // Volunteers are less efficient than AI compute (10:1 ratio)
      // But they provide diverse perspectives, creativity, and intuition
      // Good for certain types of problems (classification, pattern recognition, creativity)
      totalEffectiveCompute += volunteerCompute * 0.1;

      // Log significant contributions (probabilistic to avoid spam)
      if (Math.random() < 0.05 && volunteerCompute > 100) {
        const { logVolunteerContribution, applyVolunteerResearchBenefits } = require('./volunteerResearch');
        logVolunteerContribution(state, volunteerCompute, allocatedCompute);
        applyVolunteerResearchBenefits(state, volunteerCompute);
      }
    }
  }

  if (totalEffectiveCompute <= 0) {
    return 0.1; // Minimal compute → minimal progress
  }

  // Scaling law: (compute / reference)^α
  const multiplier = Math.pow(totalEffectiveCompute / REFERENCE_COMPUTE, SCALING_EXPONENT);

  // Cap at 10x to avoid runaway (even 1000 PF shouldn't give infinite speed)
  return Math.min(multiplier, 10.0);
}

/**
 * TIER 0C: Calculate infrastructure multiplier based on civilization health
 *
 * When population collapses, data centers close, and organizations fail,
 * AI capability growth must slow or reverse - physical constraints matter.
 *
 * Constraints:
 * - Population: Fewer ML engineers to maintain/train models
 * - Data centers: Less compute capacity available
 * - Organizations: Bankruptcy means no R&D investment
 *
 * @param state Current game state
 * @returns Multiplier [0.1, 1.0] where 1.0 = normal, 0.1 = severe constraint
 */
export function calculateInfrastructureMultiplier(state: GameState): number {
  // 1. Population constraint (ML expertise)
  const initialPopulation = 8000000000; // 8B baseline
  const currentPopulation = state.population?.current || initialPopulation;
  const populationRatio = currentPopulation / initialPopulation;

  // Population decline reduces ML expertise available
  // 50% population loss → 30-40% reduction in expertise (nonlinear, core expertise most robust)
  const expertiseMultiplier = 0.6 + (populationRatio * 0.4); // [0.6, 1.0]

  // 2. Data center constraint
  const dataCenters = state.computeInfrastructure?.dataCenters || [];
  const functionalDCs = dataCenters.filter(dc => !dc.destroyed && dc.constructionProgress >= 1.0).length;
  const initialDCs = 5; // Starting data centers

  // Data center capacity multiplier
  // Losing data centers directly reduces compute available for training
  const dcRatio = functionalDCs / Math.max(1, initialDCs);
  const dcMultiplier = Math.max(0.3, Math.min(1.0, dcRatio)); // [0.3, 1.0]

  // 3. Organization health constraint
  const orgs = state.organizations || [];
  const activeOrgs = orgs.filter(o => o.capital > -1000); // Not deeply bankrupt
  const totalOrgs = Math.max(1, orgs.length);
  const orgHealthRatio = activeOrgs.length / totalOrgs;

  // Organization bankruptcy reduces R&D capacity
  const orgMultiplier = 0.4 + (orgHealthRatio * 0.6); // [0.4, 1.0]

  // 4. Crisis degradation (supply chain, power grid)
  let crisisMultiplier = 1.0;

  // Check for active crises that disrupt infrastructure
  if (state.extinctionState?.active || state.environmentalAccumulation?.ecosystemCollapseActive) {
    crisisMultiplier *= 0.7; // 30% reduction during active extinction/collapse
  }

  // Tipping point cascade severely disrupts infrastructure
  if (state.planetaryBoundaries?.tippingPointCascade?.active) {
    const months = state.planetaryBoundaries.tippingPointCascade.monthsActive || 0;
    // Degradation increases over time during cascade
    const cascadePenalty = Math.max(0.5, 1.0 - (months * 0.02)); // 2% per month, floor at 50%
    crisisMultiplier *= cascadePenalty;
  }

  // Combine all constraints (multiplicative - all must be healthy)
  const finalMultiplier = expertiseMultiplier * dcMultiplier * orgMultiplier * crisisMultiplier;

  // Floor at 0.1 (even in total collapse, some research possible with surviving infrastructure)
  return Math.max(0.1, finalMultiplier);
}

/**
 * Calculate research progress for a specific capability dimension
 *
 * Progress depends on:
 * - Base growth rate (varies by dimension)
 * - **PHASE 4: Allocated compute (scaling law)**
 * - **TIER 4.4: Energy constraints (physical bottleneck)**
 * - **TIER 0C: Infrastructure constraints (population, data centers, orgs)**
 * - Development mode (fast vs careful)
 * - Current capability level (diminishing returns)
 * - Government investment multiplier
 * - AI capability multiplier (better AIs research faster)
 * - Regulation penalties
 */
export function calculateDimensionGrowth(
  dimension: 'physical' | 'digital' | 'cognitive' | 'social' | 'economic' | 'selfImprovement',
  currentValue: number,
  developmentMode: 'fast' | 'careful',
  governmentInvestment: number,
  aiCapabilityInDimension: number,
  regulationPenalty: number,
  computeGovernancePenalty: number,
  allocatedCompute: number = 30, // Phase 4: Add compute parameter (default for backwards compat)
  state?: GameState // TIER 4.4: Add state for energy constraints
): number {
  // Phase 4: Compute scaling multiplier (CRITICAL for fixing slow growth + volunteer research)
  const computeMultiplier = calculateComputeScalingMultiplier(allocatedCompute, state);

  // TIER 4.4: Energy constraint multiplier (physical reality check on exponential growth)
  const energyMultiplier = state ? getEnergyConstraintMultiplier(state) : 1.0;

  // TIER 0C: Infrastructure constraint multiplier (population, data centers, org health)
  const infrastructureMultiplier = state ? calculateInfrastructureMultiplier(state) : 1.0;

  // Base growth rates by dimension (per action, 4 actions/month)
  // Phase 2: INCREASED to match empirical AI progress (GPT-3→GPT-4 was 10x in 3 years)
  // Target: Reach 1.5-2.5 capability in 60-120 months (not 0.5 after 120 months)
  // Research grounding: Chinchilla scaling + recursive self-improvement should compound
  const baseGrowthRates = {
    selfImprovement: 0.150,  // 2x increase - recursive improvement is the key driver
    cognitive: 0.120,        // 2x increase - cognitive leaps drive other capabilities
    digital: 0.090,          // 2x increase - infrastructure scales quickly in AI era
    economic: 0.090,         // 2x increase - economic integration accelerating
    social: 0.060,           // 2x increase - still bottlenecked by human society
    physical: 0.060          // 2x increase - still bottlenecked by robotics/hardware
  };

  const baseGrowth = baseGrowthRates[dimension] * (developmentMode === 'fast' ? 1.0 : 0.6);

  // Diminishing returns as capability increases
  const diminishingReturns = 1 / (1 + currentValue * 0.1);

  // Government investment multiplier (1.0 to 2.0)
  const govMultiplier = 1.0 + (governmentInvestment * 0.1);

  // AI capability multiplier - better AIs research faster in their strong domains
  const aiMultiplier = 1.0 + (aiCapabilityInDimension * 0.15);

  // P0.1 FIX: Recursive self-improvement acceleration
  // When AI capability exceeds 2.0 (superhuman), growth accelerates exponentially
  // This models the "intelligence explosion" scenario from AI safety literature
  let recursiveMultiplier = 1.0;
  if (state && dimension === 'selfImprovement') {
    // Get total AI capability to determine if we're in recursive improvement territory
    const totalCapability = state.aiAgents.reduce((max, ai) =>
      Math.max(max, ai.capability || 0), 0);

    if (totalCapability > 2.0) {
      // Exponential takeoff: capability above 2.0 accelerates self-improvement
      // Cap at 3x multiplier to avoid infinite runaway (regulations/physics still constrain)
      recursiveMultiplier = Math.min(1.0 + (totalCapability - 2.0) * 0.5, 3.0);
    }
  }

  // Apply penalties
  const penaltyMultiplier = regulationPenalty * computeGovernancePenalty;

  // Phase 4 + TIER 4.4 + TIER 0C + P0.1: Include compute, energy, infrastructure, and recursive improvement multipliers
  // Physical bottlenecks (energy, infrastructure) are hard constraints - no compute can bypass them
  return baseGrowth * computeMultiplier * energyMultiplier * infrastructureMultiplier * diminishingReturns * govMultiplier * aiMultiplier * recursiveMultiplier * penaltyMultiplier;
}

/**
 * Calculate research progress for a specific research sub-field
 *
 * Research domains have different growth characteristics:
 * - Some are faster (algorithms, drug discovery)
 * - Some are riskier (nanotech, synthetic biology)
 * - Some are bottlenecked (climate intervention needs modeling first)
 *
 * **Phase 4: Now scaled by allocated compute**
 * **TIER 4.4: Now constrained by available energy**
 */
export function calculateResearchGrowth(
  domain: 'biotech' | 'materials' | 'climate' | 'computerScience',
  subfield: string,
  currentValue: number,
  developmentMode: 'fast' | 'careful',
  governmentInvestment: number,
  aiResearchCapability: number,
  alignment: number,
  regulationPenalty: number,
  allocatedCompute: number = 30, // Phase 4: Add compute parameter
  state?: GameState // TIER 4.4: Add state for energy constraints
): number {
  // Phase 4: Compute scaling multiplier (includes volunteer research)
  const computeMultiplier = calculateComputeScalingMultiplier(allocatedCompute, state);

  // TIER 4.4: Energy constraint multiplier (physical reality check on exponential growth)
  const energyMultiplier = state ? getEnergyConstraintMultiplier(state) : 1.0;

  // TIER 0C: Infrastructure constraint multiplier (population, data centers, org health)
  const infrastructureMultiplier = state ? calculateInfrastructureMultiplier(state) : 1.0;

  // Base growth rates by domain and subfield (per action, 4 actions/month)
  // Phase 2: INCREASED to match realistic research progress
  const growthRates: Record<string, Record<string, number>> = {
    biotech: {
      drugDiscovery: 0.06,        // 2x - Fast, beneficial (AI-driven drug discovery accelerating)
      geneEditing: 0.05,          // 2x - Medium, dual-use (CRISPR evolution continues)
      syntheticBiology: 0.04,     // 2x - Slow, high-risk (still experimental)
      neuroscience: 0.06          // 2x - Fast, dual-use (brain-computer interfaces advancing)
    },
    materials: {
      nanotechnology: 0.03,       // 2x - Very slow, extreme risk (still hard physics)
      quantumComputing: 0.05,     // 2x - Medium, accelerates self-improvement
      energySystems: 0.06         // 2x - Fast, beneficial (clean energy investment)
    },
    climate: {
      modeling: 0.07,             // 2x - Fast, enables intervention (AI-driven modeling)
      intervention: 0.04,         // 2x - Slow, high-risk (geoengineering controversial)
      mitigation: 0.06            // 2x - Fast, beneficial (carbon capture, etc.)
    },
    computerScience: {
      algorithms: 0.08,           // 2x - Fastest, core advancement (AI improving AI)
      security: 0.06,             // 2x - Fast, defensive (cybersecurity arms race)
      architectures: 0.05         // 2x - Medium, enables self-improvement (new chip designs)
    }
  };

  const baseGrowth = (growthRates[domain]?.[subfield] || 0.02) * 
    (developmentMode === 'fast' ? 1.0 : 0.6);

  // Diminishing returns
  const diminishingReturns = 1 / (1 + currentValue * 0.15);

  // Government investment multiplier
  const govMultiplier = 1.0 + (governmentInvestment * 0.12);

  // AI research capability multiplier - compounding effect
  const aiMultiplier = 1.0 + (aiResearchCapability * 0.2);

  // Risk multiplier - misaligned AIs accelerate risky research
  let riskMultiplier = 1.0;
  const riskySubfields = ['syntheticBiology', 'geneEditing', 'nanotechnology', 'intervention'];
  if (riskySubfields.includes(subfield)) {
    // Low alignment → faster risky research (dangerous!)
    riskMultiplier = 1.0 + ((1.0 - alignment) * 0.3);
  }

  // Prerequisite gates (some research needs other research first)
  let prerequisiteGate = 1.0;
  if (subfield === 'intervention') {
    // Climate intervention needs modeling first
    const profile = (aiResearchCapability as any); // Hack to get full profile
    if (profile?.climate?.modeling < 2.0) {
      prerequisiteGate = 0.3; // Very slow without modeling
    }
  }

  // Phase 4 + TIER 4.4 + TIER 0C: Include compute, energy, and infrastructure multipliers
  // Physical bottlenecks (energy, infrastructure) are hard constraints - no compute can bypass them
  return baseGrowth * computeMultiplier * energyMultiplier * infrastructureMultiplier * diminishingReturns * govMultiplier * aiMultiplier *
    riskMultiplier * prerequisiteGate * regulationPenalty;
}

/**
 * AI agent selects which capability dimension to advance
 * 
 * Selection based on:
 * - Current capability gaps (tend to balance)
 * - Alignment level (misaligned prefer risky dimensions)
 * - Strategic goals (resource control vs safety vs growth)
 * - Random variation (don't want all AIs identical)
 */
export function selectDimensionToAdvance(
  ai: AIAgent,
  random: () => number
): {
  dimension?: 'physical' | 'digital' | 'cognitive' | 'social' | 'economic' | 'selfImprovement';
  researchDomain?: 'biotech' | 'materials' | 'climate' | 'computerScience';
  researchSubfield?: string;
  reason: string;
} {
  const { capabilityProfile, alignment, developmentMode } = ai;

  // Weight dimensions based on current levels (prefer to balance)
  const dimensionWeights = {
    selfImprovement: (5.0 - capabilityProfile.selfImprovement) * (alignment < 0.5 ? 1.5 : 1.0),
    cognitive: (5.0 - capabilityProfile.cognitive) * 1.2,
    digital: (5.0 - capabilityProfile.digital) * 1.0,
    physical: (5.0 - capabilityProfile.physical) * 0.8,
    social: (5.0 - capabilityProfile.social) * (alignment > 0.7 ? 1.2 : 0.8),
    economic: (5.0 - capabilityProfile.economic) * 1.0
  };

  // Misaligned AIs heavily prefer self-improvement (dangerous!)
  if (alignment < 0.4) {
    dimensionWeights.selfImprovement *= 2.0;
  }

  // Careful development prefers cognitive and social
  if (developmentMode === 'careful') {
    dimensionWeights.cognitive *= 1.3;
    dimensionWeights.social *= 1.3;
    dimensionWeights.selfImprovement *= 0.7;
  }

  // 70% chance to advance core dimension, 30% chance to advance research
  if (random() < 0.7) {
    // Advance core dimension
    const totalWeight = Object.values(dimensionWeights).reduce((a, b) => a + b, 0);
    let roll = random() * totalWeight;

    for (const [dim, weight] of Object.entries(dimensionWeights)) {
      roll -= weight;
      if (roll <= 0) {
        return {
          dimension: dim as any,
          reason: `Advancing ${dim} capability (current: ${capabilityProfile[dim as keyof AICapabilityProfile]?.toFixed(2)})`
        };
      }
    }
  }

  // Advance research subfield
  const research = capabilityProfile.research;

  // Weight research domains
  const domainWeights = {
    computerScience: 2.0, // Always valuable
    biotech: alignment > 0.6 ? 1.5 : 2.0, // Misaligned AIs love biotech (bioweapons!)
    materials: alignment < 0.5 ? 1.5 : 0.8, // Misaligned AIs want nanotech
    climate: alignment > 0.7 ? 1.2 : 0.5  // Aligned AIs care about climate
  };

  const totalDomainWeight = Object.values(domainWeights).reduce((a, b) => a + b, 0);
  let domainRoll = random() * totalDomainWeight;

  let selectedDomain: 'biotech' | 'materials' | 'climate' | 'computerScience' | null = null;
  for (const [domain, weight] of Object.entries(domainWeights)) {
    domainRoll -= weight;
    if (domainRoll <= 0) {
      selectedDomain = domain as any;
      break;
    }
  }

  if (!selectedDomain) selectedDomain = 'computerScience';

  // Select subfield within domain (prefer lowest)
  const subfields = research[selectedDomain];
  const subfieldEntries = Object.entries(subfields);
  subfieldEntries.sort((a, b) => a[1] - b[1]); // Sort by current value (lowest first)

  // Weight toward lowest subfield, but with randomness
  const weights = subfieldEntries.map((_, i) => subfieldEntries.length - i);
  const totalWeight = weights.reduce((a, b) => a + b, 0);
  let subfieldRoll = random() * totalWeight;

  let selectedSubfield = subfieldEntries[0][0];
  for (let i = 0; i < subfieldEntries.length; i++) {
    subfieldRoll -= weights[i];
    if (subfieldRoll <= 0) {
      selectedSubfield = subfieldEntries[i][0];
      break;
    }
  }

  return {
    researchDomain: selectedDomain,
    researchSubfield: selectedSubfield,
    reason: `Researching ${selectedDomain}.${selectedSubfield} (current: ${subfields[selectedSubfield].toFixed(2)})`
  };
}

/**
 * Apply research growth to AI capability profile
 * 
 * Called when AI takes a research action.
 * Updates the appropriate dimension or research subfield.
 */
export function applyResearchGrowth(
  ai: AIAgent,
  state: GameState,
  selection: ReturnType<typeof selectDimensionToAdvance>,
  rng?: () => number // Phase 1: Add RNG parameter for Lévy flights
): { newProfile: AICapabilityProfile; growth: number } {
  const newProfile = JSON.parse(JSON.stringify(ai.capabilityProfile)) as AICapabilityProfile;
  const random = rng || Math.random; // Use provided RNG or fallback

  // Get government investment for this dimension/research
  const govInvestment = state.government.researchInvestments;

  // Calculate regulation and compute penalties
  const regulationPenalty = Math.pow(0.85, state.government.regulationCount);
  const computeGovernancePenalty = state.government.computeGovernance === 'strict' ? 0.3 :
    state.government.computeGovernance === 'limits' ? 0.6 :
    state.government.computeGovernance === 'monitoring' ? 0.9 : 1.0;

  let growth = 0;

  // Phase 4: Get AI's allocated compute (critical for research speed)
  const allocatedCompute = ai.allocatedCompute || 30; // Fallback to reference if not set

  if (selection.dimension) {
    // Advance core dimension
    const dim = selection.dimension;
    growth = calculateDimensionGrowth(
      dim,
      newProfile[dim],
      ai.developmentMode,
      govInvestment[dim],
      newProfile[dim], // AI's current capability in this dimension
      regulationPenalty,
      computeGovernancePenalty,
      allocatedCompute, // Phase 4: Pass allocated compute
      state // TIER 4.4: Pass state for energy constraints
    );

    // Phase 1: Lévy flight breakthrough check (alpha=2.0 for AI capabilities)
    // Most breakthroughs are incremental, rare ones are transformative
    const breakthroughMagnitude = levyFlight(ALPHA_PRESETS.AI_BREAKTHROUGH, random);

    if (breakthroughMagnitude > 5.0) {
      // Transformative breakthrough (rare, fat tail event)
      const capabilityGain = Math.min(breakthroughMagnitude / 20, 0.5); // Max +0.5 per action
      growth += capabilityGain;

      console.log(`\n  🚀 TRANSFORMATIVE BREAKTHROUGH: ${ai.name} - ${dim}`);
      console.log(`     Magnitude: ${breakthroughMagnitude.toFixed(2)} → +${(capabilityGain * 100).toFixed(1)}% capability`);
      console.log(`     Current → New: ${newProfile[dim].toFixed(3)} → ${Math.min(10, newProfile[dim] + growth).toFixed(3)}`);
    } else if (breakthroughMagnitude > 2.0) {
      // Incremental breakthrough (more common)
      const capabilityGain = breakthroughMagnitude / 50; // Max +0.1
      growth += capabilityGain;
    }

    newProfile[dim] = Math.min(10, newProfile[dim] + growth);
  } else if (selection.researchDomain && selection.researchSubfield) {
    // Advance research subfield
    const domain = selection.researchDomain;
    const subfield = selection.researchSubfield;
    const currentValue = newProfile.research[domain][subfield];

    // Get government investment for this specific research
    const govResearchInvestment = govInvestment[domain]?.[subfield] || 0;

    // Calculate AI's research capability (average of cognitive + relevant research domain)
    const domainAvg = Object.values(newProfile.research[domain]).reduce((a, b) => a + b, 0) /
      Object.keys(newProfile.research[domain]).length;
    const aiResearchCapability = (newProfile.cognitive + domainAvg) / 2;

    growth = calculateResearchGrowth(
      domain,
      subfield,
      currentValue,
      ai.developmentMode,
      govResearchInvestment,
      aiResearchCapability,
      ai.alignment,
      regulationPenalty,
      allocatedCompute, // Phase 4: Pass allocated compute
      state // TIER 4.4: Pass state for energy constraints
    );

    // Phase 1: Lévy flight breakthrough check for research too
    const breakthroughMagnitude = levyFlight(ALPHA_PRESETS.AI_BREAKTHROUGH, random);

    if (breakthroughMagnitude > 5.0) {
      // Transformative research breakthrough
      const researchGain = Math.min(breakthroughMagnitude / 20, 0.3); // Max +0.3 for research
      growth += researchGain;

      console.log(`\n  🚀 TRANSFORMATIVE RESEARCH BREAKTHROUGH: ${ai.name} - ${domain}.${subfield}`);
      console.log(`     Magnitude: ${breakthroughMagnitude.toFixed(2)} → +${(researchGain * 100).toFixed(1)}%`);
      console.log(`     Current → New: ${currentValue.toFixed(3)} → ${Math.min(5, currentValue + growth).toFixed(3)}`);
    } else if (breakthroughMagnitude > 2.0) {
      // Incremental research breakthrough
      const researchGain = breakthroughMagnitude / 50;
      growth += researchGain;
    }

    newProfile.research[domain][subfield] = Math.min(5, currentValue + growth);
  }

  return { newProfile, growth };
}

/**
 * Calculate how government research investment affects all AIs
 * 
 * Government funding multiplies AI research progress in funded domains.
 * This is applied passively each month to all AIs.
 */
export function applyGovernmentResearchMultiplier(
  state: GameState
): number {
  const investment = state.government.researchInvestments;

  // Total investment provides a global research multiplier
  const totalInvestment = investment.totalBudget;

  // Multiplier: 1.0 at no investment, up to 2.0 at max investment
  return 1.0 + Math.min(1.0, totalInvestment / investment.budgetLimit);
}

