     1→/**
     2→ * Outcome determination and probability calculations
     3→ * 
     4→ * Determines which outcome (utopia/dystopia/extinction) is occurring
     5→ * based on game state conditions.
     6→ * 
     7→ * Phase: Golden Age & Accumulation Systems
     8→ * - Golden Age detection: Immediate prosperity (fragile)
     9→ * - Utopia detection: Sustained Golden Age + low accumulation (stable)
    10→ */
    11→
    12→import { GameState, OutcomeMetrics, OutcomeType, GoldenAgeState } from '@/types/game';
    13→import { calculateQualityOfLife } from './qualityOfLife';
    14→import { getTrustInAI } from './socialCohesion';
    15→import {
    16→  getTotalAICapability as utilGetTotalAICapability,
    17→  calculateAverageAlignment as utilCalculateAverageAlignment
    18→} from './utils';
    19→
    20→/**
    21→ * Calculate total AI capability across all agents
    22→ * @deprecated Use getTotalAICapability from utils instead
    23→ */
    24→export function calculateTotalAICapability(aiAgents: { capability: number }[]): number {
    25→  return aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
    26→}
    27→
    28→/**
    29→ * Calculate average AI alignment across all agents
    30→ * @deprecated Use calculateAverageAlignment from utils instead
    31→ */
    32→export function calculateAverageAlignment(aiAgents: { alignment: number }[]): number {
    33→  if (aiAgents.length === 0) return 0;
    34→  const totalAlignment = aiAgents.reduce((sum, ai) => sum + ai.alignment, 0);
    35→  return totalAlignment / aiAgents.length;
    36→}
    37→
    38→/**
    39→ * Calculate government's effective control over AI systems
    40→ * 
    41→ * Control effectiveness decreases as AI capability grows.
    42→ * Uses exponential decay to model increasing difficulty of controlling advanced AI.
    43→ */
    44→export function calculateEffectiveControl(state: GameState): number {
    45→  const { government, aiAgents } = state;
    46→  
    47→  const totalAICapability = calculateTotalAICapability(aiAgents);
    48→  const growthFactor = 1.5; // Exponential difficulty scaling
    49→  
    50→  return government.controlDesire * government.capabilityToControl / 
    51→    (1 + Math.pow(totalAICapability, growthFactor));
    52→}
    53→
    54→/**
    55→ * Calculate outcome probabilities (utopia, dystopia, extinction)
    56→ * 
    57→ * Uses multiple factors to determine which outcome is most likely.
    58→ * Probabilities are normalized to sum to 1.0.
    59→ */
    60→export function calculateOutcomeProbabilities(state: GameState): OutcomeMetrics {
    61→  const effectiveControl = calculateEffectiveControl(state);
    62→  const qualityOfLife = calculateQualityOfLife(state.qualityOfLifeSystems);
    63→  const totalAICapability = calculateTotalAICapability(state.aiAgents);
    64→  const avgAlignment = calculateAverageAlignment(state.aiAgents);
    65→  const trustInAI = getTrustInAI(state.society); // Phase 2: Use paranoia-derived trust
    66→
    67→  // Dystopia conditions: high control, low quality of life, low trust
    68→  const dystopiaScore = Math.max(0, 
    69→    (effectiveControl > 0.8 ? 0.4 : 0) +
    70→    (qualityOfLife < 0.3 ? 0.3 : 0) +
    71→    (trustInAI < 0.3 ? 0.3 : 0)
    72→  );
    73→
    74→  // Extinction conditions: uncontrolled powerful AI with recursive improvement, low alignment
    75→  // Updated thresholds to match new balance mechanics (recursive improvement at 1.5+)
    76→  const extinctionScore = Math.max(0,
    77→    // Capability risk: Scaled to match recursive improvement thresholds
    78→    (totalAICapability > 3.0 ? 0.5 : totalAICapability > 2.0 ? 0.4 : totalAICapability > 1.5 ? 0.2 : 0) +
    79→    // Control risk: Loss of control is critical
    80→    (effectiveControl < 0.1 ? 0.3 : effectiveControl < 0.3 ? 0.15 : 0) +
    81→    // Alignment risk: Misalignment with high capability is fatal
    82→    (avgAlignment < 0.3 && totalAICapability > 1.5 ? 0.3 : avgAlignment < 0.5 && totalAICapability > 2.0 ? 0.2 : 0)
    83→  );
    84→
    85→  // Utopia conditions: high quality of life, high trust, high alignment, controlled AI
    86→  const utopiaScore = Math.max(0,
    87→    (qualityOfLife > 0.7 ? 0.3 : 0) +
    88→    (trustInAI > 0.7 ? 0.2 : 0) +
    89→    (avgAlignment > 0.7 ? 0.2 : 0) +
    90→    // Bonus for successfully managing powerful AI
    91→    (totalAICapability > 1.0 && avgAlignment > 0.6 && effectiveControl > 0.3 ? 0.3 : 0)
    92→  );
    93→
    94→  // Normalize probabilities (add small baseline to prevent division by zero)
    95→  const total = utopiaScore + dystopiaScore + extinctionScore + 0.1;
    96→  
    97→  const utopiaProbability = utopiaScore / total;
    98→  const dystopiaProbability = dystopiaScore / total;
    99→  const extinctionProbability = extinctionScore / total;
   100→  
   101→  // Determine active attractor (which outcome is "locked in")
   102→  let activeAttractor: OutcomeMetrics['activeAttractor'] = 'none';
   103→  if (utopiaProbability > 0.6) activeAttractor = 'utopia';
   104→  else if (dystopiaProbability > 0.6) activeAttractor = 'dystopia';
   105→  else if (extinctionProbability > 0.6) activeAttractor = 'extinction';
   106→  
   107→  // Lock-in strength (how committed we are to current trajectory)
   108→  const maxProb = Math.max(utopiaProbability, dystopiaProbability, extinctionProbability);
   109→  const lockInStrength = maxProb > 0.5 ? (maxProb - 0.5) * 2 : 0; // Scales 0.5-1.0 → 0-1.0
   110→  
   111→  return {
   112→    utopiaProbability,
   113→    dystopiaProbability,
   114→    extinctionProbability,
   115→    activeAttractor,
   116→    lockInStrength
   117→  };
   118→}
   119→
   120→/**
   121→ * Check if Golden Age conditions are met
   122→ * 
   123→ * Golden Age = immediate prosperity that looks great now but may be masking problems.
   124→ * 
   125→ * Entry conditions:
   126→ * - High QoL across multiple dimensions (≥ 0.7)
   127→ * - Material abundance (Stage 3+)
   128→ * - High trust (≥ 0.65)
   129→ * - Low active conflict
   130→ * - Economic stability
   131→ */
   132→export function checkGoldenAgeConditions(state: GameState): {
   133→  met: boolean;
   134→  reason: string;
   135→} {
   136→  const qol = calculateQualityOfLife(state.qualityOfLifeSystems);
   137→  const trust = getTrustInAI(state.society); // Phase 2: Use paranoia-derived trust
   138→  const economicStage = state.globalMetrics.economicTransitionStage;
   139→  const socialStability = state.globalMetrics.socialStability;
   140→  const avgAlignment = calculateAverageAlignment(state.aiAgents);
   141→  
   142→  // High QoL threshold
   143→  if (qol < 0.7) {
   144→    return { met: false, reason: 'QoL below Golden Age threshold' };
   145→  }
   146→  
