if (state.psychologicalTrauma && state.psychologicalTrauma.traumaLevel > 0) {
  const traumaLevel = state.psychologicalTrauma.traumaLevel;
  const traumaPenalty = Math.pow(traumaLevel, 1.5); // Non-linear penalty

  // Reduce psychological wellbeing dimension
  if (qol.psychological) {
    qol.psychological *= (1 - traumaPenalty);
  }

  // Reduce social QoL
  if (qol.social) {
    qol.social *= (1 - traumaPenalty * 0.5);
  }

  // Log significant trauma impact
  if (traumaPenalty > 0.25) {
    console.log(`\n  💔 Psychological trauma impact: -${(traumaPenalty * 100).toFixed(0)}% wellbeing, -${(traumaPenalty * 50).toFixed(0)}% social`);
  }
}

// Also reduce institutional trust (trauma erodes trust in institutions)
if (state.psychologicalTrauma && state.psychologicalTrauma.traumaLevel > 0.3) {
  const traumaErosion = state.psychologicalTrauma.traumaLevel * 0.3;
  state.government.legitimacy *= (1 - traumaErosion);
  state.socialCohesion *= (1 - traumaErosion * 0.5);
}
```

### Step 5: Register Phase in Orchestrator

**File:** `src/simulation/engine/phases/index.ts`

Add export:
```typescript
