     1→/**
     2→ * Multi-dimensional Quality of Life system (Phase 1)
     3→ * 
     4→ * Tracks 17 QoL dimensions across 5 categories to enable "dark valley" dynamics
     5→ * where some dimensions can decline while others are maintained.
     6→ */
     7→
     8→import { QualityOfLifeSystems, GameState } from '@/types/game';
     9→import { getTrustInAI } from './socialCohesion';
    10→
    11→/**
    12→ * Environmental mortality breakdown by cause
    13→ */
    14→export interface EnvironmentalMortalityBreakdown {
    15→  total: number;           // Total monthly mortality rate
    16→  famine: number;          // Deaths from food insecurity
    17→  disease: number;         // Deaths from water/sanitation
    18→  climate: number;         // Deaths from heat/disasters
    19→  ecosystem: number;       // Deaths from biodiversity loss
    20→  pollution: number;       // Deaths from pollution (baseline)
    21→}
    22→
    23→/**
    24→ * Calculate environmental mortality rate based on threshold crossings
    25→ *
    26→ * Research-based (UNEP 2024, PNAS 2014):
    27→ * - Current (2025): 7/9 boundaries, 9M deaths/8B people = 0.009% monthly
    28→ * - Mortality scales with food, water, climate, biodiversity thresholds
    29→ * - Non-linear escalation when multiple systems fail
    30→ *
    31→ * FIX (Oct 13, 2025): Now returns breakdown by cause to properly track deaths
    32→ * P0.6 (Oct 15, 2025): Episodic environmental shocks instead of continuous noise
    33→ * Research: Real environmental disasters are episodic (heatwaves, droughts, famines)
    34→ *   - Events occur with ~5% monthly probability based on environmental stress
    35→ *   - Events cause 50-200% mortality spikes for 3-12 months
    36→ *   - Between events: minimal variation (baseline + small noise)
    37→ * Returns monthly mortality rate (0-1, where 0.01 = 1% die per month)
    38→ */
    39→export function calculateEnvironmentalMortality(state: GameState, month: number): EnvironmentalMortalityBreakdown {
    40→  const env = state.environmentalAccumulation;
    41→  const boundaries = state.planetaryBoundariesSystem;
    42→  if (!env || !boundaries) {
    43→    return { total: 0, famine: 0, disease: 0, climate: 0, ecosystem: 0, pollution: 0 };
    44→  }
    45→  
    46→  let famineMortality = 0;
    47→  let diseaseMortality = 0;
    48→  let climateMortality = 0;
    49→  let ecosystemMortality = 0;
    50→  let pollutionMortality = 0;
    51→  
    52→  // === BASELINE (Current 2025 conditions) ===
    53→  // 7/9 boundaries breached = 0.009% monthly (UNEP: 9M deaths/year globally)
    54→  // Pollution is the main driver of current baseline mortality
    55→  if (boundaries.boundariesBreached >= 7) {
    56→    pollutionMortality = 0.00009; // 0.009% baseline
    57→  }
    58→  
    59→  // === FOOD SECURITY (Highest immediate impact) ===
    60→  // Food < 0.4 = crisis, Food < 0.2 = catastrophic
    61→  // FIX (Oct 13, 2025): foodSecurity is in survivalFundamentals, not environmentalAccumulation
    62→  const foodSecurity = state.survivalFundamentals?.foodSecurity ?? 0.7;
    63→  if (foodSecurity < 0.4) {
    64→    const foodSeverity = (0.4 - foodSecurity) / 0.4; // 0-1 scale
    65→    famineMortality += 0.0001 * Math.pow(foodSeverity, 1.5); // 0.01%/month at threshold, scales up
    66→    
    67→    if (foodSecurity < 0.2) {
    68→      // Catastrophic food crisis: additional mortality
    69→      const catSeverity = (0.2 - foodSecurity) / 0.2;
    70→      famineMortality += 0.0005 * catSeverity; // Up to 0.05%/month additional
    71→    }
    72→  }
    73→  
    74→  // === WATER SECURITY ===
    75→  // Water < 0.4 = crisis (leads to cholera, dysentery, other waterborne disease)
    76→  const waterSecurity = env.waterSecurity || 0.7;
    77→  if (waterSecurity < 0.4) {
    78→    const waterSeverity = (0.4 - waterSecurity) / 0.4;
    79→    diseaseMortality += 0.00008 * Math.pow(waterSeverity, 1.5); // Slightly less immediate than food
    80→  }
    81→  
    82→  // === CLIMATE STABILITY (Heat stress, disasters) ===
    83→  // Climate < 0.5 = severe, Climate < 0.3 = catastrophic
    84→  const climateStability = env.climateStability || 0.75;
    85→  if (climateStability < 0.6) {
    86→    const climateSeverity = (0.6 - climateStability) / 0.6;
    87→    climateMortality += 0.00005 * Math.pow(climateSeverity, 2); // Non-linear escalation
    88→  }
    89→  
    90→  // === BIODIVERSITY LOSS (Ecosystem services collapse) ===
    91→  // Biodiversity < 0.3 = critical, < 0.2 = collapse
    92→  // Loss of pollination, disease regulation, etc.
    93→  const biodiversity = env.biodiversityIndex || 0.35;
    94→  if (biodiversity < 0.3) {
    95→    const bioSeverity = (0.3 - biodiversity) / 0.3;
    96→    ecosystemMortality += 0.00003 * Math.pow(bioSeverity, 1.5); // Pollination, disease regulation lost
    97→  }
    98→  
    99→  // === CASCADE AMPLIFICATION (Non-Linear Feedback) ===
   100→  // When multiple systems fail simultaneously, effects compound
   101→  const breachedCount = boundaries.boundariesBreached;
   102→  if (breachedCount >= 8) {
   103→    const cascadeAmplifier = 1.0 + Math.pow((breachedCount - 7) / 2, 2); // 1.0x → 2.25x at 9/9
   104→    famineMortality *= cascadeAmplifier;
   105→    diseaseMortality *= cascadeAmplifier;
   106→    climateMortality *= cascadeAmplifier;
   107→    ecosystemMortality *= cascadeAmplifier;
   108→  }
   109→
   110→  // === P0.6 (Oct 15, 2025): PERSISTENT ENVIRONMENTAL SHOCKS (AR1 autocorrelation) ===
   111→  // Research: Real disasters persist for 3-12 months (not single-month events)
   112→  // - 2003 European heatwave: Sustained for 3 months, 40,000 deaths
   113→  // - Somalia famine 2010-12: 24 months, 256,000 deaths
   114→  // - Agricultural shocks: 3-6 month recovery periods
   115→
   116→  // Initialize activeShocks array if missing
   117→  if (!env.activeShocks) {
   118→    env.activeShocks = [];
   119→  }
   120→
   121→  // === APPLY ACTIVE SHOCKS (persistent mortality spikes) ===
   122→  for (const shock of env.activeShocks) {
   123→    // Apply shock magnitude to appropriate mortality type
   124→    switch (shock.type) {
   125→      case 'climate':
   126→        climateMortality *= shock.magnitude;
   127→        break;
   128→      case 'famine':
   129→        famineMortality *= shock.magnitude;
   130→        break;
   131→      case 'disease':
   132→        diseaseMortality *= shock.magnitude;
   133→        break;
   134→      case 'ecosystem':
   135→        ecosystemMortality *= shock.magnitude;
   136→        break;
   137→    }
   138→  }
   139→
   140→  // === DECAY ACTIVE SHOCKS (AR1 persistence) ===
   141→  // Remove expired shocks and decrement remaining months
   142→  env.activeShocks = env.activeShocks.filter(shock => {
   143→    shock.remainingMonths--;
   144→    return shock.remainingMonths > 0;
   145→  });
   146→
   147→  // === GENERATE NEW SHOCKS (episodic events) ===
   148→  // P0.7 (Oct 16, 2025): Scenario-specific shock parameters
   149→  // Historical: 2% base + scaling = 2-15% event probability, 150-300% spikes
   150→  // Unprecedented: 5% base + scaling = 5-25% event probability, 250-450% spikes
   151→  const scenarioParams = state.config.scenarioParameters;
   152→  const baseProb = scenarioParams?.environmentalShockProbability ?? 0.02;
   153→  const maxProb = baseProb + 0.13; // Scale to 13% above base
   154→  const baseMag = scenarioParams?.environmentalShockMagnitude ?? 2.0;
   155→
   156→  // Event probability scales with environmental stress
   157→  const eventProbability = Math.min(maxProb, baseProb + (breachedCount / 9) * (maxProb - baseProb));
   158→
   159→  if (Math.random() < eventProbability) {
   160→    // New shock triggered!
   161→    const shockType = Math.random();
   162→    const shockMagnitude = baseMag + Math.random() * (baseMag * 0.75); // baseMag to (baseMag * 1.75)
   163→    const shockDuration = 3 + Math.floor(Math.random() * 10); // 3-12 months
   164→
   165→    // Determine shock type (which mortality category)
   166→    let type: 'climate' | 'famine' | 'disease' | 'ecosystem';
   167→    if (shockType < 0.3) {
   168→      type = 'climate'; // Heatwave / extreme weather
   169→    } else if (shockType < 0.6) {
   170→      type = 'famine'; // Drought / crop failure
   171→    } else if (shockType < 0.85) {
   172→      type = 'disease'; // Disease outbreak / waterborne disease
   173→    } else {
   174→      type = 'ecosystem'; // Ecosystem collapse event
   175→    }
   176→
   177→    // Add to active shocks
   178→    env.activeShocks.push({
   179→      type,
   180→      magnitude: shockMagnitude,
   181→      startMonth: month,
   182→      duration: shockDuration,
   183→      remainingMonths: shockDuration
   184→    });
   185→
   186→    // Log shock event
   187→    console.log(`\n🌍💥 ENVIRONMENTAL SHOCK: ${type.toUpperCase()}`);
   188→    console.log(`   Magnitude: ${(shockMagnitude * 100 - 100).toFixed(0)}% mortality spike`);
   189→    console.log(`   Duration: ${shockDuration} months`);
   190→    console.log(`   Month: ${month}\n`);
   191→  }
   192→
   193→  // === BASELINE NOISE (±5%) ===
   194→  // Small variation between events (not continuous dice-rolling)
   195→  const baselineNoise = () => 0.95 + Math.random() * 0.1; // 95-105%
   196→  famineMortality *= baselineNoise();
   197→  diseaseMortality *= baselineNoise();
   198→  climateMortality *= baselineNoise();
   199→  ecosystemMortality *= baselineNoise();
   200→  pollutionMortality *= baselineNoise();
   201→  
   202→  // === REGIONAL VARIATION MULTIPLIER ===
   203→  // Some regions hit harder (handled by regional crisis system)
   204→  // This is the global average; specific regions can be 2-5x worse
   205→  
   206→  const total = famineMortality + diseaseMortality + climateMortality + ecosystemMortality + pollutionMortality;
   207→  
   208→  // Cap at 10%/month (horrific but not instant extinction)
   209→  // Even worst-case scenarios take years to play out
   210→  const cappedTotal = Math.min(total, 0.10);
   211→  
   212→  // Scale down individual categories if we hit the cap
   213→  const scaleFactor = total > 0.10 ? 0.10 / total : 1.0;
   214→  
   215→  return {
   216→    total: cappedTotal,
   217→    famine: famineMortality * scaleFactor,
   218→    disease: diseaseMortality * scaleFactor,
   219→    climate: climateMortality * scaleFactor,
   220→    ecosystem: ecosystemMortality * scaleFactor,
   221→    pollution: pollutionMortality * scaleFactor
   222→  };
   223→}
   224→
   225→/**
   226→ * Calculate multi-dimensional quality of life from all component systems
   227→ * 
   228→ * This replaces the simple QoL calculation with a nuanced system that tracks:
   229→ * - Basic needs (30%): material, energy, safety
   230→ * - Psychological (25%): mental health, meaning, connection, autonomy
   231→ * - Social (20%): freedom, information, community, culture
   232→ * - Health (15%): healthcare, longevity, disease burden
   233→ * - Environmental (10%): ecosystem, climate, pollution
   234→ * 
   235→ * Enables "dark valley" dynamics where some dimensions can drop
   236→ * while others are maintained, allowing recovery trajectories
   237→ * 
   238→ * @param systems - The quality of life dimensions to aggregate
   239→ * @returns Weighted quality of life score [0, ~1.5] where 1.0 is "good"
   240→ */
   241→export function calculateQualityOfLife(systems: QualityOfLifeSystems): number {
   242→  // Basic Needs (30% weight)
   243→  const basicNeeds = (
   244→    systems.materialAbundance * 0.4 +    // Food, shelter, goods
   245→    systems.energyAvailability * 0.3 +   // Energy access
   246→    systems.physicalSafety * 0.3          // Safety from violence
   247→  ) * 0.3;
   248→  
   249→  // Psychological Needs (25% weight)
   250→  const psychological = (
   251→    systems.mentalHealth * 0.3 +         // Mental wellness
   252→    systems.meaningAndPurpose * 0.3 +    // Life satisfaction
   253→    systems.socialConnection * 0.2 +      // Relationships
   254→    systems.autonomy * 0.2                // Self-determination
   255→  ) * 0.25;
   256→  
   257→  // Social Needs (20% weight)
   258→  const social = (
   259→    systems.politicalFreedom * 0.3 +     // Democracy, rights
   260→    systems.informationIntegrity * 0.3 +  // Truth vs propaganda
   261→    systems.communityStrength * 0.2 +     // Local cohesion
   262→    systems.culturalVitality * 0.2        // Art, creativity
   263→  ) * 0.2;
   264→  
   265→  // Health and Longevity (15% weight)
   266→  const health = (
   267→    systems.healthcareQuality * 0.4 +    // Medical outcomes
   268→    systems.longevityGains * 0.3 +        // Lifespan increases
   269→    (1 - systems.diseasesBurden) * 0.3    // Low disease burden
   270→  ) * 0.15;
   271→  
   272→  // Environmental (10% weight)
   273→  const environmental = (
   274→    systems.ecosystemHealth * 0.4 +      // Nature, biodiversity
   275→    systems.climateStability * 0.3 +      // Stable weather
   276→    (1 - systems.pollutionLevel) * 0.3    // Clean air/water
   277→  ) * 0.1;
   278→  
   279→  return basicNeeds + psychological + social + health + environmental;
   280→}
   281→
   282→/**
   283→ * Initialize quality of life systems with baseline values
   284→ * Represents early 2025 starting conditions
   285→ */
   286→export function initializeQualityOfLifeSystems(): QualityOfLifeSystems {
   287→  return {
   288→    // NEW: Survival Fundamentals (Oct 12, 2025)
   289→    // Baseline 2025: Most people have food/water/shelter, but stressed
   290→    survivalFundamentals: {
