   296→    
   297→    // Basic Needs - moderate in developed world
   298→    materialAbundance: 0.8,
   299→    energyAvailability: 0.9,
   300→    physicalSafety: 0.85,
   301→    
   302→    // Psychological - struggling but functional
   303→    mentalHealth: 0.6,
   304→    meaningAndPurpose: 0.65,
   305→    socialConnection: 0.55,
   306→    autonomy: 0.7,
   307→    
   308→    // Social - mixed democratic health
   309→    politicalFreedom: 0.7,
   310→    informationIntegrity: 0.5, // Low due to social media
   311→    communityStrength: 0.5,
   312→    culturalVitality: 0.7,
   313→    
   314→    // Health - good but room for improvement
   315→    healthcareQuality: 0.75,
   316→    longevityGains: 0.1, // Slight gains above historical baseline
   317→    diseasesBurden: 0.3,
   318→    
   319→    // Environmental - declining
   320→    ecosystemHealth: 0.4,
   321→    climateStability: 0.6,
   322→    pollutionLevel: 0.5,
   323→    
   324→    // NEW: Distribution Metrics (Oct 12, 2025)
   325→    // Baseline 2025: Moderate inequality, some regional crises
   326→    distribution: {
   327→      globalGini: 0.38,              // Current global Gini ~0.38 (World Bank)
   328→      regionalVariance: 0.08,        // Moderate variance
   329→      crisisAffectedFraction: 0.15,  // ~15% in acute crisis zones (conflicts, droughts)
   330→      worstRegionQoL: 0.35,          // Worst regions (conflict zones, extreme poverty)
   331→      bestRegionQoL: 0.95,           // Best regions (Nordic countries, high HDI)
   332→      medianRegionQoL: 0.65,         // Median region
   333→      isDystopicInequality: false,   // Not yet dystopian
