   339→/**
   340→ * Update all quality of life dimensions based on current game state
   341→ * 
   342→ * This function calculates how each QoL dimension changes based on:
   343→ * - Economic conditions (unemployment, stage, wealth)
   344→ * - AI impacts (beneficial/harmful actions, capability)
   345→ * - Government policies (legitimacy, control, regulations)
   346→ * - Social dynamics (adaptation, trust, stability)
   347→ * 
   348→ * Returns updated QoL systems that can then be aggregated via calculateQualityOfLife()
   349→ */
   350→export function updateQualityOfLifeSystems(state: GameState): QualityOfLifeSystems {
   351→  const { globalMetrics, society, aiAgents, government, qualityOfLifeSystems: current } = state;
   352→  
   353→  const totalAICapability = aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
   354→  const avgAlignment = aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / Math.max(1, aiAgents.length);
   355→  const beneficialActions = aiAgents.reduce((sum, ai) => sum + ai.beneficialActions, 0);
   356→  const harmfulActions = aiAgents.reduce((sum, ai) => sum + ai.harmfulActions, 0);
   357→  const economicStage = globalMetrics.economicTransitionStage;
   358→  
   359→  // Phase 1.2: Check for UBI (strengthens safety net effects)
   360→  const hasUBI = government.activeRegulations.some(reg => reg.includes('UBI'));
   361→  const ubiVariant = government.structuralChoices.ubiVariant || 'none';
   362→  const hasGenerousUBI = ubiVariant === 'generous';
   363→  
   364→  // === BASIC NEEDS ===
   365→  
   366→  // Material abundance: AI capability helps, unemployment hurts, stage matters
   367→  const aiProductionBonus = totalAICapability * avgAlignment * 0.1;
   368→
   369→  // POLICY CALIBRATION (Oct 17, 2025): Unemployment penalty recalibrated
   370→  // Research: COVID-19 at 14.7% unemployment caused:
   371→  // - +40% food insecurity (USDA 2020: 10.5% → 21%)
   372→  // - +12% homelessness (Eviction Lab 2020)
   373→  // - +30% depression (Kessler et al. 2008)
   374→  // Suggests ~-0.5 multiplier for realistic impact
   375→  // At 54% unemployment: -0.27 penalty → QoL drops from ~78% to ~50% (catastrophic without UBI)
   376→  // @see Kahneman & Deaton (2010) - Income-life satisfaction relationship
   377→  const unemploymentPenalty = society.unemploymentLevel * (economicStage < 3 ? -0.5 : 0.1); // Becomes positive in post-scarcity
   378→  const wealthBonus = globalMetrics.wealthDistribution * 0.3;
   379→  let materialAbundance = 0.8 + aiProductionBonus + unemploymentPenalty + wealthBonus;
   380→  
   381→  // POLICY CALIBRATION (Oct 17, 2025): UBI floor works at ALL stages
   382→  // Research: Texas/Illinois 2024 pilots showed 6.4% well-being improvement (Kangas et al.)
   383→  // BUG FIX: UBI was only active at economicStage >= 3, but validation runs at stage < 3
   384→  // FIX: UBI now provides graduated floor at all stages, matching empirical evidence
   385→  //
   386→  // Stage-based UBI floors:
   387→  // - Stage 0-2 (pre-transition): Modest safety net (0.55-0.65) - matches pilot data
   388→  // - Stage 3+ (post-scarcity transition): Strong floor (0.75-0.90) - prevents unemployment collapse
   389→  //
   390→  // @see research/policy-interventions-systemic-inequality-validation_20251016.md
   391→  // @see Kangas et al. (2024) - Texas/Illinois UBI pilots: 6.4% life satisfaction improvement
   392→  if (hasUBI) {
   393→    // Calculate stage-appropriate floor
   394→    let ubiFloor: number;
   395→    if (economicStage >= 3) {
   396→      // Post-scarcity transition: Strong UBI floor (prevents unemployment from destroying QoL)
   397→      ubiFloor = hasGenerousUBI ? 0.90 : 0.75;
   398→    } else {
   399→      // Pre-transition: Modest UBI floor (matches pilot program evidence)
   400→      // Research: Texas/Illinois pilots at $1000/month improved well-being ~6-8%
   401→      // Starting from baseline material abundance ~0.50-0.60 → floor at 0.55-0.65
   402→      ubiFloor = hasGenerousUBI ? 0.65 : 0.55;
   403→    }
   404→    materialAbundance = Math.max(materialAbundance, ubiFloor);
   405→  }
   406→  
   407→  // === FOOD SECURITY PENALTY (Oct 13, 2025) ===
   408→  // FIX: Material abundance should reflect actual food availability
   409→  // Can't have high "material abundance" if people are starving
   410→  const env = state.environmentalAccumulation;
   411→  // FIX (Oct 13, 2025): foodSecurity is in survivalFundamentals, not environmentalAccumulation
   412→  const foodSecurity = state.survivalFundamentals?.foodSecurity ?? 0.7;
   413→  
   414→  if (foodSecurity < 0.7) {
   415→    // Food crisis directly reduces material abundance
   416→    // Research: 2007-08 food crisis, 2022 Ukraine war food shock
   417→    const foodPenalty = (0.7 - foodSecurity) * 1.5; // Up to -1.05 at food = 0
   418→    materialAbundance -= foodPenalty;
   419→  }
   420→  
   421→  // Phase 1.1: Post-scarcity QoL multipliers (FIXED: Scale with population)
   422→  if (economicStage >= 4) {
   423→    // CRITICAL FIX: Scale abundance by population survival
   424→    // If 95% of people dead, infrastructure collapses even with super-AI
   425→    const pop = state.humanPopulationSystem;
   426→    const populationFraction = pop.population / pop.baselinePopulation;
   427→    
   428→    // Population scaling: 30% minimum (scattered survivors), 100% at full population
   429→    // Below 50% population: Severe infrastructure decay
   430→    // Below 10% population: Near-total collapse
   431→    const infrastructureScaling = populationFraction < 0.5 
   432→      ? 0.3 + (populationFraction * 0.7)  // 30-65% scaling (< 4B people)
   433→      : 0.65 + (populationFraction * 0.35); // 65-100% scaling (> 4B people)
   434→    
   435→    // Full automation → material abundance (scaled by who's alive to benefit)
   436→    materialAbundance += 0.8 * infrastructureScaling;
   437→    
   438→    // AI capability accelerates abundance (but only if infrastructure intact)
   439→    // Cap AI contribution to prevent infinite values
   440→    const aiContribution = Math.min(1.2, totalAICapability * 0.15);
   441→    materialAbundance += aiContribution * infrastructureScaling;
   442→    
   443→    // Cap at reasonable post-scarcity levels (no infinite abundance)
   444→    materialAbundance = Math.min(3.0, Math.max(0, materialAbundance));
   445→  } else {
   446→    materialAbundance = Math.max(0, Math.min(2, materialAbundance));
   447→  }
   448→  
   449→  // === POPULATION COLLAPSE PENALTY (ALL STAGES) ===
   450→  // FIX (Oct 13): Apply population scaling to ALL stages, not just Stage 4
   451→  // 95% mortality = infrastructure collapse regardless of AI capability
   452→  const pop = state.humanPopulationSystem;
   453→  const populationFraction = pop.population / pop.baselinePopulation;
   454→  
   455→  if (populationFraction < 0.5) {
   456→    // 50%+ population loss → severe material scarcity
   457→    // Supply chains broken, distribution networks fail, looting, hoarding
   458→    const collapseMultiplier = populationFraction < 0.1 
   459→      ? 0.1  // < 10% survivors: total collapse
   460→      : 0.1 + (populationFraction * 0.9); // 10-50% survivors: proportional
   461→    
   462→    materialAbundance *= collapseMultiplier;
   463→  }
   464→  
   465→  // Energy availability: AI helps, stage advances
   466→  let energyAvailability = 0.9 + totalAICapability * 0.05 + economicStage * 0.1;
   467→  
   468→  // Phase 1.1: Post-scarcity energy abundance (FIXED: Scale with population)
   469→  if (economicStage >= 4) {
   470→    const pop = state.humanPopulationSystem;
   471→    const populationFraction = pop.population / pop.baselinePopulation;
   472→    
   473→    // Energy infrastructure requires maintenance crews
   474→    const gridScaling = populationFraction < 0.5 
   475→      ? 0.3 + (populationFraction * 0.7)
   476→      : 0.65 + (populationFraction * 0.35);
   477→    
   478→    // Renewable/fusion breakthrough assumption at Stage 4
   479→    energyAvailability += 0.6 * gridScaling;
   480→    
   481→    // AI optimization of energy systems (capped to prevent infinite)
   482→    const aiEnergyBonus = Math.min(1.0, totalAICapability * 0.1);
   483→    energyAvailability += aiEnergyBonus * gridScaling;
   484→    
   485→    // Cap at reasonable post-scarcity levels
   486→    energyAvailability = Math.min(3.0, Math.max(0, energyAvailability));
   487→  } else {
   488→    energyAvailability = Math.max(0, Math.min(2, energyAvailability));
   489→  }
   490→  
   491→  // === POPULATION COLLAPSE PENALTY (ENERGY) ===
   492→  // FIX (Oct 13): Energy grids fail without maintenance crews
   493→  if (populationFraction < 0.5) {
   494→    // 50%+ dead → grid operators, maintenance, repairs all failing
   495→    const gridCollapseMultiplier = populationFraction < 0.1 
   496→      ? 0.15  // < 10%: mostly dark, scattered generators
   497→      : 0.15 + (populationFraction * 0.85);
   498→    
   499→    energyAvailability *= gridCollapseMultiplier;
   500→  }
   501→  
   502→  // Physical safety: Stability matters, harmful AI reduces, government control helps
   503→  let physicalSafety = globalMetrics.socialStability * 0.8 + government.legitimacy * 0.2;
   504→  physicalSafety -= harmfulActions * 0.05;
   505→  
   506→  // Phase 1.1: Post-scarcity reduces scarcity-driven crime/conflict
   507→  if (economicStage >= 4 && materialAbundance > 1.5) {
   508→    physicalSafety += 0.2; // Less crime when everyone has enough
   509→  }
   510→  
   511→  physicalSafety = Math.max(0, Math.min(1, physicalSafety));
   512→  
   513→  // === PSYCHOLOGICAL NEEDS ===
   514→  
   515→  // Mental health: Economic stress hurts, stability helps, meaning helps
   516→  let mentalHealth = 0.6;
   517→  mentalHealth += globalMetrics.socialStability * 0.3;
   518→  mentalHealth -= society.unemploymentLevel * (economicStage < 3 ? 0.4 : -0.2); // Unemployment becomes freedom later
   519→  mentalHealth += current.meaningAndPurpose * 0.2;
   520→  
   521→  // POLICY CALIBRATION (Oct 17, 2025): UBI reduces economic anxiety at ALL stages
   522→  // Research: Texas/Illinois 2024 pilots showed mental health improvements
   523→  // BUG FIX: Was only active at economicStage >= 3, but validation runs at stage < 3
   524→  if (hasUBI) {
   525→    // UBI reduces stress from unemployment/economic insecurity
   526→    // Graduated effect by economic stage
   527→    let stressReduction: number;
   528→    if (economicStage >= 3) {
   529→      // Post-scarcity transition: Larger mental health benefit
   530→      stressReduction = hasGenerousUBI ? 0.20 : 0.12;
   531→    } else {
   532→      // Pre-transition: Modest but meaningful mental health improvement
   533→      // Research: UBI pilots reduce anxiety, improve well-being ~6-8%
   534→      stressReduction = hasGenerousUBI ? 0.10 : 0.06;
   535→    }
   536→    mentalHealth += stressReduction;
   537→  }
   538→  
   539→  // Phase 1.1: Post-scarcity reduces economic anxiety
   540→  if (economicStage >= 4 && materialAbundance > 1.5) {
   541→    mentalHealth += 0.15; // Less stress when material needs are effortlessly met
   542→  }
   543→  
   544→  mentalHealth = Math.max(0, Math.min(1, mentalHealth));
   545→  
   546→  // Meaning and purpose: Post-work transition matters
   547→  let meaningAndPurpose = 0.65;
   548→  if (economicStage >= 3 && society.unemploymentLevel > 0.6) {
   549→    // Transition crisis: meaning drops then recovers
   550→    meaningAndPurpose = 0.4 + (economicStage - 3) * 0.2;
   551→  } else if (economicStage >= 4) {
   552→    // Post-scarcity: high meaning from freedom
   553→    meaningAndPurpose = 0.8 + totalAICapability * 0.05;
   554→  }
   555→  meaningAndPurpose = Math.max(0, Math.min(1, meaningAndPurpose));
   556→  
   557→  // Social connection: Community strength during crisis, atomization risk with abundance
   558→  let socialConnection = 0.55 + current.communityStrength * 0.3;
   559→  if (globalMetrics.socialStability < 0.4) {
   560→    // Crisis brings people together
   561→    socialConnection += 0.2;
   562→  } else if (materialAbundance > 1.5) {
   563→    // Abundance can isolate
   564→    socialConnection -= 0.1;
   565→  }
   566→  socialConnection = Math.max(0, Math.min(1, socialConnection));
   567→  
   568→  // Autonomy: Government control reduces, AI surveillance reduces, freedom helps
   569→  // Phase 2.6: STRONGER penalties for high surveillance
   570→  let autonomy = 0.7;
   571→  autonomy -= government.controlDesire * 0.3;
   572→  autonomy -= government.structuralChoices.surveillanceLevel * 0.4; // Increased from 0.2
   573→  if (government.structuralChoices.surveillanceLevel > 0.7) {
   574→    // Pervasive surveillance: feels like living in 1984
   575→    autonomy -= 0.3;
   576→  }
   577→  autonomy += current.politicalFreedom * 0.2;
   578→  
   579→  // Phase 2.7: AUTONOMY FLOOR - Tech & governance can counter surveillance
   580→  // Research basis: Zuboff (2019), Lessig (2006) - "Code is law, but code can be rewritten"
   581→  const govQuality = government.governanceQuality;
   582→  const democraticFloor = government.governmentType === 'democratic' ? 0.25 : 
   583→                          government.governmentType === 'technocratic' ? 0.15 : 0.05;
   584→  const transparencyFloor = (govQuality?.transparency || 0.5) * 0.15;
   585→  const participationFloor = (govQuality?.participationRate || 0.5) * 0.10;
   586→  
   587→  // Breakthrough tech can provide counter-surveillance tools
   588→  const autonomyBreakthrough = state.breakthroughTech;
   589→  const counterSurveillanceTech = 
   590→    (autonomyBreakthrough.communityPlatforms?.deploymentLevel || 0) * 0.15 + // Decentralized communication
   591→    (autonomyBreakthrough.purposeFrameworks?.deploymentLevel || 0) * 0.10;    // Self-actualization pathways
   592→  
   593→  const minimumAutonomy = democraticFloor + transparencyFloor + participationFloor + counterSurveillanceTech;
   594→  
   595→  autonomy = Math.max(minimumAutonomy, Math.min(1, autonomy));
   596→  
   597→  // === SOCIAL NEEDS ===
   598→  
   599→  // Political freedom: Government legitimacy matters, control desire reduces
   600→  // Phase 2.6: Authoritarian governments reduce freedom more
   601→  let politicalFreedom = government.legitimacy * 0.7 + (1 - government.controlDesire) * 0.3;
   602→  if (government.governmentType === 'authoritarian') {
   603→    politicalFreedom *= 0.5; // Authoritarian = low freedom
   604→  } else if (government.governmentType === 'democratic') {
   605→    politicalFreedom *= 1.1; // Democratic bonus
   606→  }
   607→  // High surveillance reduces freedom
   608→  if (government.structuralChoices.surveillanceLevel > 0.7) {
   609→    politicalFreedom -= 0.3;
   610→  }
   611→  // Crisis can reduce freedoms
   612→  if (globalMetrics.socialStability < 0.3) {
   613→    politicalFreedom *= 0.8;
   614→  }
   615→  politicalFreedom = Math.max(0, Math.min(1, politicalFreedom));
   616→  
   617→  // Information integrity: AI manipulation hurts, trust matters
   618→  const trustInAI = getTrustInAI(society); // Phase 2: Use paranoia-derived trust
   619→  let informationIntegrity = 0.5 + trustInAI * 0.3;
   620→  informationIntegrity -= (totalAICapability * (1 - avgAlignment)) * 0.2; // Misaligned AI manipulates
   621→  informationIntegrity = Math.max(0, Math.min(1, informationIntegrity));
   622→  
   623→  // Community strength: Adaptation helps, stability helps
   624→  let communityStrength = 0.5 + society.socialAdaptation * 0.3 + globalMetrics.socialStability * 0.2;
   625→  
   626→  // Phase 2.7: Tech & economic stage boost community
   627→  const communityBreakthrough = state.breakthroughTech;
   628→  const communityTechBoost = (communityBreakthrough.communityPlatforms?.deploymentLevel || 0) * 0.15; // Digital community tools
   629→  const postScarcityBoost = economicStage >= 3 ? 0.10 : 0; // Time freedom enables community
   630→  const ubiBoost = hasUBI ? 0.05 : 0; // Reduces economic stress
   631→  
   632→  communityStrength += communityTechBoost + postScarcityBoost + ubiBoost;
   633→  communityStrength = Math.max(0, Math.min(1, communityStrength));
   634→  
   635→  // Cultural vitality: Freedom helps, AI can enhance or suppress
   636→  let culturalVitality = 0.7 + politicalFreedom * 0.2;
   637→  if (totalAICapability > 1.0 && avgAlignment > 0.7) {
   638→    // Aligned AI enhances culture
   639→    culturalVitality += 0.1;
   640→  }
   641→  culturalVitality = Math.max(0, Math.min(1, culturalVitality));
   642→  
   643→  // === HEALTH AND LONGEVITY ===
   644→  
   645→  // Healthcare quality: AI capability helps significantly
   646→  let healthcareQuality = 0.75 + totalAICapability * avgAlignment * 0.15;
   647→  healthcareQuality = Math.max(0, Math.min(1, healthcareQuality));
   648→  
   649→  // Longevity gains: AI medical breakthroughs
   650→  let longevityGains = 0.1 + totalAICapability * avgAlignment * 0.1;
   651→  longevityGains = Math.max(0, Math.min(2, longevityGains));
   652→  
   653→  // Diseases burden: AI helps reduce, but new risks from misaligned AI
   654→  let diseasesBurden = 0.3 - totalAICapability * avgAlignment * 0.1;
   655→  diseasesBurden += harmfulActions * 0.02; // Bioweapon risk
   656→  diseasesBurden = Math.max(0, Math.min(1, diseasesBurden));
   657→  
   658→  // === ENVIRONMENTAL ===
   659→  
   660→  // Ecosystem health: AI can help or hurt
   661→  let ecosystemHealth = 0.4;
   662→  if (totalAICapability > 1.5 && avgAlignment > 0.7) {
   663→    // Advanced aligned AI can restore ecosystems
   664→    ecosystemHealth += (totalAICapability - 1.5) * 0.2;
   665→  } else if (totalAICapability > 2.0 && avgAlignment < 0.5) {
   666→    // Misaligned AI may damage ecosystems for resources
   667→    ecosystemHealth -= 0.2;
   668→  }
   669→  ecosystemHealth = Math.max(0, Math.min(1, ecosystemHealth));
   670→  
   671→  // Climate stability: Slow degradation unless AI intervenes
   672→  let climateStability = current.climateStability - 0.002; // Slow decline
   673→  if (totalAICapability > 1.5 && avgAlignment > 0.7) {
   674→    // Advanced aligned AI can stabilize climate
   675→    climateStability += 0.01;
   676→  }
   677→  climateStability = Math.max(0, Math.min(1, climateStability));
   678→  
   679→  // Pollution level: Economic activity matters, AI can help
   680→  let pollutionLevel = 0.5 + economicStage * 0.05 - totalAICapability * avgAlignment * 0.1;
   681→  pollutionLevel = Math.max(0, Math.min(1, pollutionLevel));
   682→  
   683→  // === BREAKTHROUGH TECHNOLOGY BOOSTS (Phase 2A) ===
   684→  if (state.breakthroughTech) {
   685→    const { getTechnologyQoLBoosts } = require('./breakthroughTechnologies');
   686→    const techBoosts = getTechnologyQoLBoosts(state);
   687→    
   688→    // Apply mental health boosts from mental health tech + purpose frameworks
   689→    mentalHealth = Math.min(1.5, mentalHealth + techBoosts.mentalHealth);
   690→    
   691→    // Apply healthcare boosts from medical breakthroughs
   692→    healthcareQuality = Math.min(1.5, healthcareQuality + techBoosts.healthcare);
   693→    
   694→    // Apply environmental boosts from clean energy + ecosystem management
   695→    ecosystemHealth = Math.min(1.0, ecosystemHealth + techBoosts.environmental);
   696→    climateStability = Math.min(1.0, climateStability + techBoosts.environmental * 0.5);
   697→  }
   698→  
   699→  // === SURVIVAL FUNDAMENTALS (Oct 12, 2025) ===
   700→  // Calculate core survival metrics separately from aggregate QoL
   701→  const rawFoodSecurity = calculateFoodSecurity(state);
   702→  const rawWaterSecurity = calculateWaterSecurity(state);
   703→  const rawThermalHabitability = calculateThermalHabitability(state);
   704→  const rawShelterSecurity = calculateShelterSecurity(state);
   705→  
   706→  // NaN guards for survival fundamentals
   707→  const survivalFundamentals = {
   708→    foodSecurity: isNaN(rawFoodSecurity) ? 0.85 : rawFoodSecurity,
   709→    waterSecurity: isNaN(rawWaterSecurity) ? 0.80 : rawWaterSecurity,
   710→    thermalHabitability: isNaN(rawThermalHabitability) ? 1.0 : rawThermalHabitability,
   711→    shelterSecurity: isNaN(rawShelterSecurity) ? 0.75 : rawShelterSecurity,
   712→  };
   713→  
   714→  // FIX (Oct 13, 2025): Assign survivalFundamentals to state!
   715→  // BUG: Was calculated but never assigned → state.survivalFundamentals always undefined → famines never trigger!
   716→  state.survivalFundamentals = survivalFundamentals;
   717→  
   718→  // === DISTRIBUTION METRICS (Oct 12, 2025) ===
   719→  // Calculate regional inequality to detect dystopian outcomes
   720→  const distribution = calculateDistributionMetrics(
   721→    state,
   722→    survivalFundamentals,
   723→    {
   724→      materialAbundance,
   725→      energyAvailability,
   726→      physicalSafety,
   727→      mentalHealth,
   728→      healthcareQuality
   729→    }
   730→  );
   731→  
   732→  // === REGIONAL INEQUALITY TRACKING (DEPRECATED - kept for backward compatibility) ===
   733→  const regionalInequality = calculateRegionalInequality(state, {
   734→    materialAbundance,
   735→    energyAvailability,
   736→    physicalSafety,
   737→    mentalHealth,
   738→    healthcareQuality
   739→  });
   740→  
   741→  return {
   742→    // NEW: Survival fundamentals (required)
   743→    survivalFundamentals,
   744→    
   745→    // Basic needs
   746→    materialAbundance,
   747→    energyAvailability,
   748→    physicalSafety,
   749→    
   750→    // Psychological
   751→    mentalHealth,
   752→    meaningAndPurpose,
   753→    socialConnection,
   754→    autonomy,
   755→    
   756→    // Social
   757→    politicalFreedom,
   758→    informationIntegrity,
   759→    communityStrength,
   760→    culturalVitality,
   761→    
   762→    // Health
   763→    healthcareQuality,
   764→    longevityGains,
   765→    diseasesBurden,
   766→    
   767→    // Environmental
   768→    ecosystemHealth,
   769→    climateStability,
   770→    pollutionLevel,
   771→    
   772→    // NEW: Distribution metrics (required)
   773→    distribution,
   774→    
   775→    // DEPRECATED (backward compatibility)
   776→    regionalInequality
   777→  };
   778→}
   779→
   780→/**
   781→ * Calculate regional QoL inequality (Oct 12, 2025)
   782→ * 
   783→ * Global averages hide massive suffering - some regions in famine while others abundant.
   784→ * This tracks the variance in QoL across crisis-affected vs. non-affected regions.
   785→ */
   786→function calculateRegionalInequality(
   787→  state: GameState,
   788→  avgQoL: {
   789→    materialAbundance: number;
   790→    energyAvailability: number;
   791→    physicalSafety: number;
   792→    mentalHealth: number;
   793→    healthcareQuality: number;
   794→  }
   795→): {
   796→  giniCoefficient: number;
   797→  topRegionQoL: number;
   798→  bottomRegionQoL: number;
   799→  qolGap: number;
   800→  crisisAffectedPopulation: number;
   801→} {
   802→  const env = state.environmentalAccumulation;
   803→  const social = state.socialAccumulation;
   804→  const pop = state.humanPopulationSystem;
   805→  const refugees = state.refugeeCrisisSystem;
   806→  
   807→  // Estimate crisis-affected population
   808→  // Based on active crises, refugee counts, and population decline
   809→  let crisisAffectedPopulation = 0;
   810→  
   811→  // Environmental crises affect specific regions
   812→  if (env.resourceCrisisActive) crisisAffectedPopulation += 0.25; // Food/water insecure regions
   813→  if (env.climateCatastropheActive) crisisAffectedPopulation += 0.15; // Coastal & vulnerable
   814→  if (env.ecosystemCollapseActive) crisisAffectedPopulation += 0.10; // Ecosystem-dependent
   815→  
   816→  // Social crises affect specific demographics
   817→  if (social.meaningCollapseActive) crisisAffectedPopulation += 0.30; // Wealthy automated nations
   818→  if (social.socialUnrestActive) crisisAffectedPopulation += 0.20; // Urban centers
   819→  
   820→  // Refugees are definitely crisis-affected
   821→  if (refugees && refugees.activeCrises) {
   822→    const refugeePopulation = Object.values(refugees.activeCrises)
   823→      .reduce((sum, crisis) => sum + crisis.totalFled, 0);
   824→    crisisAffectedPopulation += (refugeePopulation / 1000) / pop.population; // millions to billions
   825→  }
   826→  
   827→  // Cap at 100%
   828→  crisisAffectedPopulation = Math.min(1.0, crisisAffectedPopulation);
   829→  
   830→  // Calculate bottom region QoL (crisis-affected)
   831→  // These regions experience the full brunt of crises
   832→  const crisisMultiplier = 0.3; // 70% reduction in crisis zones
   833→  const bottomRegionQoL = (
   834→    avgQoL.materialAbundance * crisisMultiplier * 0.3 +
   835→    avgQoL.energyAvailability * crisisMultiplier * 0.3 +
   836→    avgQoL.physicalSafety * crisisMultiplier * 0.2 +
   837→    avgQoL.mentalHealth * crisisMultiplier * 0.1 +
   838→    avgQoL.healthcareQuality * crisisMultiplier * 0.1
   839→  );
   840→  
   841→  // Calculate top region QoL (non-affected or benefiting)
   842→  // These regions may even benefit from AI abundance
   843→  const benefitMultiplier = crisisAffectedPopulation > 0.3 ? 1.3 : 1.1;
   844→  const topRegionQoL = (
   845→    avgQoL.materialAbundance * benefitMultiplier * 0.3 +
   846→    avgQoL.energyAvailability * benefitMultiplier * 0.3 +
   847→    avgQoL.physicalSafety * Math.min(1, avgQoL.physicalSafety * 1.2) * 0.2 +
   848→    avgQoL.mentalHealth * Math.min(1, avgQoL.mentalHealth * 1.1) * 0.1 +
   849→    avgQoL.healthcareQuality * Math.min(1, avgQoL.healthcareQuality * 1.2) * 0.1
   850→  );
   851→  
   852→  const qolGap = topRegionQoL - bottomRegionQoL;
   853→  
   854→  // Calculate Gini coefficient (0 = perfect equality, 1 = extreme inequality)
   855→  // Simple approximation: If crisis affects 30% at 0.3x QoL and 70% at 1.3x QoL
   856→  // Gini increases with both the gap and the population affected
   857→  const giniCoefficient = Math.min(1.0, 
   858→    qolGap * 0.5 + // Gap contribution
   859→    crisisAffectedPopulation * 0.3 // Population affected contribution
   860→  );
   861→  
   862→  return {
   863→    giniCoefficient,
   864→    topRegionQoL,
   865→    bottomRegionQoL,
   866→    qolGap,
   867→    crisisAffectedPopulation
   868→  };
   869→}
