   871→/**
   872→ * SURVIVAL FUNDAMENTALS CALCULATIONS (Oct 12, 2025)
   873→ * 
   874→ * These track whether people's basic survival needs are met.
   875→ * Unlike aggregate metrics, these focus on worst-case and cannot be averaged away.
   876→ */
   877→
   878→/**
   879→ * Calculate food security across population
   880→ * 
   881→ * Research basis:
   882→ * - FAO: 1800+ kcal/day minimum for survival
   883→ * - Food security = availability + access + utilization + stability
   884→ * - Phosphorus depletion, ocean collapse, water stress, temperature all affect food
   885→ */
   886→export function calculateFoodSecurity(state: GameState): number {
   887→  const resources = state.resourceEconomy;
   888→  const phosphorus = state.phosphorusDepletion;
   889→  const ocean = state.oceanAcidification;
   890→  const freshwater = state.freshwaterDepletion;
   891→  
   892→  // Base food availability from resource stocks
   893→  let foodSecurity = Math.min(1.0, resources.food.currentStock / 100);
   894→  
   895→  // === PHOSPHORUS DEPLETION ===
   896→  // Low reserves = reduced agricultural yields
   897→  if (phosphorus && phosphorus.reserves < 0.50) {
   898→    const depletionPenalty = (0.50 - phosphorus.reserves) * 0.8;
   899→    foodSecurity -= depletionPenalty;
   900→  }
   901→  
   902→  // High phosphorus prices = food price crisis (access problem)
   903→  // Research: 2007-08 food crisis saw 4x prices, 40M+ pushed into poverty
   904→  if (phosphorus && phosphorus.priceIndex > 2.0) {
   905→    const priceAccessPenalty = Math.min(0.4, (phosphorus.priceIndex - 2.0) * 0.05);
   906→    foodSecurity -= priceAccessPenalty;
   907→  }
   908→  
   909→  // === OCEAN ACIDIFICATION ===
   910→  // Marine food web collapse affects 3 billion fish-dependent people
   911→  // Research: 37.5% of global population relies on fish as primary protein
   912→  if (ocean && ocean.marineFoodWebCollapseActive) {
   913→    const fishDependentPenalty = ocean.fishDependentImpact * 0.375;
   914→    foodSecurity -= fishDependentPenalty;
   915→  }
   916→  
   917→  // === FRESHWATER STRESS ===
   918→  // Agriculture uses 70% of freshwater - stress directly impacts food production
   919→  if (freshwater && freshwater.waterStress > 0.50) {
   920→    const waterPenalty = (freshwater.waterStress - 0.50) * 0.6;
   921→    foodSecurity -= waterPenalty;
   922→  }
   923→  
   924→  // === TEMPERATURE STRESS ===
   925→  // Research: Each 1°C above 1.5°C reduces crop yields 10-15%
   926→  // Major crops (wheat, rice, maize) have temperature optima
   927→  const tempAnomaly = resources.co2.temperatureAnomaly;
   928→  if (tempAnomaly > 1.5) {
   929→    const climatePenalty = (tempAnomaly - 1.5) * 0.15; // 15% per degree
   930→    foodSecurity -= climatePenalty;
   931→  }
   932→  
   933→  // === BIODIVERSITY LOSS ===
   934→  // Research: IPBES (2016), Bardgett & van der Putten (2014), FAO soil reports
   935→  // Biodiversity loss affects food security through multiple pathways:
   936→  // 1. Pollinator decline (35% of crops depend on animal pollinators)
   937→  // 2. Soil health degradation (95% of food comes from soil)
   938→  // 3. Loss of natural pest control
   939→  if (state.biodiversitySystem) {
   940→    const globalBio = state.biodiversitySystem.globalBiodiversityIndex;
   941→    
   942→    // Pollination crisis
   943→    // IPBES: 35% of global food crops depend on pollinators
   944→    // Threshold at 80% biodiversity (pollinators decline faster than general biodiversity)
   945→    if (globalBio < 0.80) {
   946→      const pollinatorLoss = 0.80 - globalBio;
   947→      const pollinationPenalty = pollinatorLoss * 0.35; // Up to 35% loss at bio=45%
   948→      foodSecurity -= pollinationPenalty;
   949→    }
   950→    
   951→    // Soil health degradation
   952→    // Microbiomes, decomposers, nutrient cycling
   953→    // 95% of food comes from soil
   954→    if (globalBio < 0.60) {
   955→      const soilHealthLoss = 0.60 - globalBio;
   956→      const soilPenalty = soilHealthLoss * 0.25; // Up to 25% loss at bio=35%
   957→      foodSecurity -= soilPenalty;
   958→    }
   959→    
   960→    // Natural pest control loss
   961→    // Without predators: 20-30% higher crop losses
   962→    if (globalBio < 0.50) {
   963→      const pestControlLoss = 0.50 - globalBio;
   964→      const pestPenalty = pestControlLoss * 0.20; // Up to 20% loss at bio=30%
   965→      foodSecurity -= pestPenalty;
   966→    }
   967→  }
   968→  
   969→  // === AI ENHANCEMENT ===
   970→  // Aligned superintelligent AI can help food production
   971→  // Precision agriculture, vertical farms, synthetic biology
   972→  const totalAI = state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
   973→  const avgAlignment = state.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / Math.max(1, state.aiAgents.length);
   974→  if (totalAI > 1.5 && avgAlignment > 0.7) {
   975→    const aiAgriculture = Math.min(0.3, (totalAI - 1.5) * 0.1);
   976→    foodSecurity += aiAgriculture;
   977→  }
   978→  
   979→  // === BREAKTHROUGH TECHNOLOGY ===
   980→  // Sustainable agriculture: closed-loop systems, hydroponics, cellular agriculture
   981→  const sustainableAg = state.breakthroughTech.sustainableAgriculture?.deploymentLevel || 0;
   982→  foodSecurity += sustainableAg * 0.3; // Up to +30% food security
   983→  
   984→  return Math.max(0, Math.min(1.5, foodSecurity));
   985→}
