   987→/**
   988→ * Get regional population proportion
   989→ * Used for calculating population at risk in regional famines
   990→ */
   991→function getRegionalPopulationProportion(regionName: string): number {
   992→  const proportions: Record<string, number> = {
   993→    'Asia': 0.60,         // 4.7B / 8B
   994→    'Africa': 0.18,       // 1.4B / 8B
   995→    'South America': 0.05, // 0.43B / 8B
   996→    'North America': 0.07, // 0.58B / 8B
