  1003→/**
  1004→ * Check regional biodiversity for famine risk
  1005→ * Triggers famines when regional ecosystems collapse
  1006→ * 
  1007→ * Research: IPBES (2019), FAO State of Food Security (2024)
  1008→ * Ecosystem collapse → agricultural failure → famine
  1009→ */
  1010→export function checkRegionalFamineRisk(state: GameState, month: number): void {
  1011→  if (!state.famineSystem) {
  1012→    console.warn(`⚠️  [Month ${month}] checkRegionalFamineRisk: famineSystem is undefined!`);
  1013→    return;
  1014→  }
  1015→  
  1016→  // FIX (Oct 13, 2025): foodSecurity is in survivalFundamentals, NOT environmentalAccumulation!
  1017→  // BUG: Was checking env.foodSecurity (undefined) → always defaulted to 0.7 → never triggered!
  1018→  const env = state.environmentalAccumulation;
  1019→  const globalFoodSecurity = state.survivalFundamentals?.foodSecurity ?? 0.7;
  1020→  
  1021→  // FIX (Oct 13, 2025): Simplified famine trigger based on global food security only
  1022→  // The regional biodiversity system isn't being maintained, so we can't rely on it
  1023→  // Research: FAO, IPBES - food security < 0.4 = famine risk
  1024→  
  1025→  if (globalFoodSecurity < 0.4) {
  1026→    const totalPopulation = state.humanPopulationSystem.population;
  1027→    
  1028→    // Define 6 major world regions (simplified, not tied to biodiversity system)
  1029→    const worldRegions = [
  1030→      { name: 'Asia', popFraction: 0.60 },
  1031→      { name: 'Africa', popFraction: 0.18 },
  1032→      { name: 'Europe', popFraction: 0.09 },
  1033→      { name: 'North America', popFraction: 0.07 },
  1034→      { name: 'South America', popFraction: 0.05 },
  1035→      { name: 'Oceania', popFraction: 0.01 }
  1036→    ];
  1037→    
  1038→    // How many regions to trigger famine in, based on severity
  1039→    // Research: Severe food crisis affects multiple regions simultaneously
  1040→    const regionsToTrigger = globalFoodSecurity < 0.1 ? 6 :  // Global famine
  1041→                             globalFoodSecurity < 0.2 ? 4 :  // Severe crisis (Asia, Africa, ...)
  1042→                             globalFoodSecurity < 0.3 ? 2 :  // Major crisis (Asia, Africa)
  1043→                             1;                              // Regional crisis (Asia)
  1044→    
  1045→    for (let i = 0; i < regionsToTrigger; i++) {
  1046→      const region = worldRegions[i];
  1047→      
  1048→      // Skip if famine already active in this region
  1049→      const existingFamine = state.famineSystem.activeFamines.find(
  1050→        f => f.affectedRegion === region.name
  1051→      );
  1052→      if (existingFamine) continue;
  1053→      
  1054→      // Calculate population at risk
  1055→      // Research: Severe food crisis puts 30-80% of regional population at risk
  1056→      const severityFactor = (0.4 - globalFoodSecurity) / 0.4; // 0-1 scale
  1057→      const atRiskFraction = 0.30 + (severityFactor * 0.50); // 30-80% at risk
  1058→      const populationAtRisk = totalPopulation * region.popFraction * atRiskFraction;
  1059→      
  1060→      // Determine cause
  1061→      let cause: import('../types/famine').FamineCause = 'crop_failure';
  1062→      if (state.phosphorusDepletion?.globalSupplyShock > 3.0) {
  1063→        cause = 'supply_chain_collapse';
  1064→      } else if (env.climateStability < 0.4) {
  1065→        cause = 'drought';
  1066→      }
  1067→      
  1068→      // Trigger famine with realistic death curve (2% → 8% → 15% → 10% → 2% over months)
  1069→      const { triggerFamine } = require('../types/famine');
  1070→      triggerFamine(
  1071→        state.famineSystem,
  1072→        month,
  1073→        region.name,
  1074→        populationAtRisk,
  1075→        cause,
  1076→        globalFoodSecurity
  1077→      );
  1078→      
  1079→      console.log(`\n🌾💀 GLOBAL FOOD CRISIS FAMINE: ${region.name}`);
  1080→      console.log(`   Global food security: ${(globalFoodSecurity * 100).toFixed(1)}%`);
  1081→      console.log(`   Population at risk: ${(populationAtRisk * 1000).toFixed(0)}M (${(atRiskFraction * 100).toFixed(0)}% of region)`);
  1082→      console.log(`   Cause: ${cause}`);
  1083→      console.log(`   Expected deaths: ~${(populationAtRisk * 0.37 * 1000).toFixed(0)}M over 6 months if no intervention\n`);
  1084→    }
  1085→  }
  1086→}
