  1088→/**
  1089→ * Calculate water security across population
  1090→ * 
  1091→ * Research basis:
  1092→ * - WHO: 50L/day minimum for health (drinking, cooking, hygiene)
  1093→ * - 20L/day survival minimum
  1094→ * - Freshwater depletion, climate change, pollution all threaten water access
  1095→ */
  1096→export function calculateWaterSecurity(state: GameState): number {
  1097→  const resources = state.resourceEconomy;
  1098→  const freshwater = state.freshwaterDepletion;
  1099→  const ocean = state.oceanAcidification;
  1100→  
  1101→  // Base water availability from resource stocks
  1102→  let waterSecurity = Math.min(1.0, resources.water.reserves);
  1103→  
  1104→  // === FRESHWATER DEPLETION ===
  1105→  // Day Zero droughts = acute water crisis
  1106→  if (freshwater && freshwater.dayZeroDrought.active) {
  1107→    const droughtSeverity = freshwater.dayZeroDrought.severity;
  1108→    waterSecurity -= droughtSeverity * 0.4; // Up to 40% reduction
  1109→  }
  1110→  
  1111→  // Peak Groundwater = declining availability
  1112→  if (freshwater && freshwater.peakGroundwater.active) {
  1113→    const depletionRate = freshwater.peakGroundwater.depletionRate;
  1114→    waterSecurity -= depletionRate * 0.3;
  1115→  }
  1116→  
  1117→  // General water stress
  1118→  if (freshwater && freshwater.waterStress > 0.40) {
  1119→    const stressPenalty = (freshwater.waterStress - 0.40) * 0.5;
  1120→    waterSecurity -= stressPenalty;
  1121→  }
  1122→  
  1123→  // === CLIMATE IMPACT ===
  1124→  // Temperature anomalies disrupt water cycle
  1125→  // Research: Each 1°C = 7% more atmospheric water vapor = more droughts AND floods
  1126→  const tempAnomaly = resources.co2.temperatureAnomaly;
  1127→  if (tempAnomaly > 2.0) {
  1128→    const climatePenalty = (tempAnomaly - 2.0) * 0.1;
  1129→    waterSecurity -= climatePenalty;
  1130→  }
  1131→  
  1132→  // === POLLUTION ===
  1133→  // Novel entities (PFAS, microplastics) contaminate water supplies
  1134→  if (state.novelEntities && state.novelEntities.pfasConcentration > 70) {
  1135→    const contamination = (state.novelEntities.pfasConcentration - 70) / 30; // 70-100 scale
  1136→    waterSecurity -= contamination * 0.15; // Up to 15% reduction
  1137→  }
  1138→  
  1139→  // === AI ENHANCEMENT ===
  1140→  // Desalination, water purification, infrastructure optimization
  1141→  const totalAI = state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
  1142→  const avgAlignment = state.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / Math.max(1, state.aiAgents.length);
  1143→  if (totalAI > 1.5 && avgAlignment > 0.7) {
  1144→    const aiWater = Math.min(0.25, (totalAI - 1.5) * 0.08);
  1145→    waterSecurity += aiWater;
  1146→  }
  1147→  
  1148→  // === BREAKTHROUGH TECHNOLOGY ===
  1149→  // Clean energy enables desalination at scale
  1150→  const cleanEnergy = state.breakthroughTech.cleanEnergy?.deploymentLevel || 0;
  1151→  waterSecurity += cleanEnergy * 0.15; // Desalination powered by clean energy
  1152→  
  1153→  return Math.max(0, Math.min(1.5, waterSecurity));
  1154→}
  1155→
  1156→/**
  1157→ * Calculate thermal habitability of planet
  1158→ * 
  1159→ * Research basis:
  1160→ * - Sherwood & Huber (2010): Wet-bulb 35°C = death in ~6 hours
  1161→ * - IPCC: +2°C makes Middle East, Pakistan, India marginal
  1162→ * - +4°C: Tropical belt dangerous for outdoor work
  1163→ */
  1164→export function calculateThermalHabitability(state: GameState): number {
  1165→  const tempAnomaly = state.resourceEconomy.co2.temperatureAnomaly;
  1166→  
  1167→  // Base habitability by temperature anomaly
  1168→  let habitableFraction = 1.0;
  1169→  
  1170→  if (tempAnomaly < 1.5) {
  1171→    // Below Paris Agreement target: Fully habitable with adaptation
  1172→    habitableFraction = 1.0;
  1173→  } else if (tempAnomaly < 2.5) {
  1174→    // 1.5-2.5°C: Regional impacts
  1175→    // Middle East, Pakistan, North India become marginal (~15% of land area)
  1176→    // Research: Wet-bulb temps regularly exceed 31°C (dangerous for outdoor work)
  1177→    habitableFraction = 0.85 - (tempAnomaly - 1.5) * 0.15;
  1178→  } else if (tempAnomaly < 4.0) {
  1179→    // 2.5-4°C: Tropical belt becomes dangerous
  1180→    // ~35% of land area affected (all tropics + sub-tropics)
  1181→    // Research: Wet-bulb temps approach 35°C during heat waves
  1182→    habitableFraction = 0.70 - (tempAnomaly - 2.5) * 0.20;
  1183→  } else if (tempAnomaly < 6.0) {
  1184→    // 4-6°C: Civilizational threat
  1185→    // 50%+ of land area regularly uninhabitable in summer
  1186→    habitableFraction = Math.max(0.20, 0.40 - (tempAnomaly - 4.0) * 0.10);
  1187→  } else {
  1188→    // >6°C: Hothouse Earth scenario
  1189→    // Only polar regions habitable
  1190→    habitableFraction = Math.max(0.05, 0.20 - (tempAnomaly - 6.0) * 0.05);
  1191→  }
  1192→  
  1193→  // === ADAPTATION FACTORS ===
  1194→  // AI can help with cooling infrastructure, but can't change physics
  1195→  const totalAI = state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
  1196→  const avgAlignment = state.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / Math.max(1, state.aiAgents.length);
  1197→  
  1198→  // Advanced AI can provide adaptation infrastructure
  1199→  // But this only helps marginally - can't make 40°C wet-bulb survivable
  1200→  if (totalAI > 2.0 && avgAlignment > 0.7 && tempAnomaly < 4.0) {
  1201→    const adaptationBonus = Math.min(0.10, (totalAI - 2.0) * 0.03);
  1202→    habitableFraction += adaptationBonus;
  1203→  }
  1204→  
  1205→  // Climate engineering technology (risky but possible)
  1206→  const geoengineering = state.breakthroughTech.climateEngineering?.deploymentLevel || 0;
  1207→  if (geoengineering > 0.5) {
  1208→    // Can offset some warming, but risky and imperfect
  1209→    habitableFraction += geoengineering * 0.15;
  1210→  }
  1211→  
  1212→  return Math.max(0, Math.min(1.0, habitableFraction));
  1213→}
  1214→
  1215→/**
  1216→ * Calculate shelter security across population
  1217→ * 
  1218→ * Research basis:
  1219→ * - Housing as human right (UN)
  1220→ * - Climate refugees from uninhabitable regions
  1221→ * - Economic access to housing (wealth distribution)
  1222→ */
  1223→export function calculateShelterSecurity(state: GameState): number {
  1224→  const society = state.society;
  1225→  const refugees = state.refugeeCrisisSystem;
  1226→  const wealth = state.globalMetrics.wealthDistribution;
  1227→  const ubiActive = state.government.activeRegulations.some(reg => reg.includes('UBI'));
  1228→  
  1229→  // Base shelter security from wealth distribution
  1230→  // Research: Housing insecurity correlates with income inequality
  1231→  let shelterSecurity = 0.7 + wealth * 0.2;
  1232→  
  1233→  // === REFUGEE CRISES ===
  1234→  // Displaced populations lose housing
  1235→  if (refugees && refugees.activeCrises) {
  1236→    const totalRefugees = Object.values(refugees.activeCrises)
  1237→      .reduce((sum, crisis) => sum + crisis.totalFled, 0);
  1238→    const refugeeFraction = (totalRefugees / 1000) / state.humanPopulationSystem.population; // millions to billions
  1239→    shelterSecurity -= refugeeFraction * 0.5; // Refugees have poor shelter access
  1240→  }
  1241→  
  1242→  // === CLIMATE DISPLACEMENT ===
  1243→  // Temperature anomalies force migration from uninhabitable regions
  1244→  const tempAnomaly = state.resourceEconomy.co2.temperatureAnomaly;
  1245→  if (tempAnomaly > 2.5) {
  1246→    // Significant displacement from tropics
  1247→    const displacementPenalty = (tempAnomaly - 2.5) * 0.08;
  1248→    shelterSecurity -= displacementPenalty;
  1249→  }
  1250→  
  1251→  // === ECONOMIC SECURITY ===
  1252→  // Unemployment without safety net = housing insecurity
  1253→  const unemployment = society.unemploymentLevel;
  1254→  const economicStage = state.globalMetrics.economicTransitionStage;
  1255→  
  1256→  if (economicStage < 3 && unemployment > 0.4 && !ubiActive) {
  1257→    // High unemployment without UBI = homelessness risk
  1258→    const economicPenalty = (unemployment - 0.4) * 0.3;
  1259→    shelterSecurity -= economicPenalty;
  1260→  }
  1261→  
  1262→  // === AI ENHANCEMENT ===
  1263→  // AI can optimize housing construction, prefab housing, resource allocation
  1264→  const totalAI = state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
  1265→  const avgAlignment = state.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / Math.max(1, state.aiAgents.length);
  1266→  
  1267→  if (totalAI > 1.5 && avgAlignment > 0.7) {
  1268→    const aiHousing = Math.min(0.2, (totalAI - 1.5) * 0.06);
  1269→    shelterSecurity += aiHousing;
  1270→  }
  1271→  
  1272→  // === POST-SCARCITY ===
  1273→  // Stage 4: Housing becomes abundant
  1274→  if (economicStage >= 4) {
  1275→    shelterSecurity += 0.2;
  1276→  }
  1277→  
  1278→  // === UBI FLOOR ===
  1279→  // POLICY CALIBRATION (Oct 17, 2025): UBI floor works at ALL stages
  1280→  // UBI ensures minimum housing security (rental assistance, housing vouchers)
  1281→  // BUG FIX: Was only active at economicStage >= 3, but validation runs at stage < 3
  1282→  if (ubiActive) {
  1283→    const ubiVariant = state.government.structuralChoices.ubiVariant || 'none';
  1284→    let ubiFloor: number;
  1285→    if (economicStage >= 3) {
  1286→      // Post-scarcity: Housing becomes much more accessible
  1287→      ubiFloor = ubiVariant === 'generous' ? 0.85 : 0.70;
  1288→    } else {
  1289→      // Pre-transition: Modest shelter floor (rental assistance prevents homelessness)
  1290→      // Research: UBI pilots reduce homelessness risk ~30-40%
  1291→      ubiFloor = ubiVariant === 'generous' ? 0.68 : 0.60;
  1292→    }
  1293→    shelterSecurity = Math.max(shelterSecurity, ubiFloor);
  1294→  }
  1295→  
  1296→  return Math.max(0, Math.min(1.0, shelterSecurity));
  1297→}
  1298→
  1299→/**
  1300→ * ENHANCED DISTRIBUTION METRICS (Oct 12, 2025)
  1301→ * 
  1302→ * Calculate QoL inequality across regions to detect dystopian scenarios where
  1303→ * aggregate metrics look fine but specific populations suffer.
  1304→ * 
  1305→ * Research basis:
  1306→ * - Wilkinson & Pickett (2009): Gini >0.45 = social instability
  1307→ * - Rawls: Justice requires maximizing the welfare of the worst-off
  1308→ * - "Two worlds" dystopia: Some thrive while others suffer
  1309→ */
  1310→export function calculateDistributionMetrics(
  1311→  state: GameState,
  1312→  survivalFundamentals: {
  1313→    foodSecurity: number;
  1314→    waterSecurity: number;
  1315→    thermalHabitability: number;
  1316→    shelterSecurity: number;
  1317→  },
  1318→  basicQoL: {
  1319→    materialAbundance: number;
  1320→    energyAvailability: number;
  1321→    physicalSafety: number;
  1322→    mentalHealth: number;
  1323→    healthcareQuality: number;
  1324→  }
  1325→): {
  1326→  globalGini: number;
  1327→  regionalVariance: number;
  1328→  crisisAffectedFraction: number;
  1329→  worstRegionQoL: number;
  1330→  bestRegionQoL: number;
  1331→  medianRegionQoL: number;
  1332→  isDystopicInequality: boolean;
  1333→  isRegionalDystopia: boolean;
  1334→} {
  1335→  const regions = state.regionalPopulations;
  1336→  const env = state.environmentalAccumulation;
  1337→  const social = state.socialAccumulation;
  1338→  const refugees = state.refugeeCrisisSystem;
  1339→  const pop = state.humanPopulationSystem;
  1340→  
  1341→  // Calculate QoL for each region
  1342→  const regionalQoLs: number[] = [];
  1343→  let totalCrisisAffected = 0;
  1344→  
  1345→  if (regions && regions.regions) {
  1346→    for (const region of regions.regions) {
  1347→      // Region-specific modifiers based on crisis exposure
  1348→      let regionQoL = 0;
  1349→      
  1350→      // === SURVIVAL FUNDAMENTALS (weighted heavily) ===
  1351→      // These are most affected by regional crises
  1352→      let regionFoodSecurity = survivalFundamentals.foodSecurity;
  1353→      let regionWaterSecurity = survivalFundamentals.waterSecurity;
  1354→      let regionShelter = survivalFundamentals.shelterSecurity;
  1355→      
  1356→      // Water stress affects specific regions more
  1357→      if (region.freshwaterStress > 0.7) {
  1358→        regionWaterSecurity *= (1 - region.freshwaterStress * 0.5);
  1359→        regionFoodSecurity *= (1 - region.freshwaterStress * 0.3); // Agriculture needs water
  1360→      }
  1361→      
  1362→      // Drought-affected regions
  1363→      if (region.droughtAffected) {
  1364→        regionWaterSecurity *= 0.4; // 60% reduction in drought zones
  1365→        regionFoodSecurity *= 0.5; // 50% reduction
  1366→      }
  1367→      
  1368→      // Resource vulnerability (food import dependency)
  1369→      if (region.resourceVulnerability > 0.7) {
  1370→        regionFoodSecurity *= (1 - region.resourceVulnerability * 0.4);
  1371→      }
  1372→      
  1373→      // Refugee hosting strains infrastructure
  1374→      if (region.refugeesHosted > 0) {
  1375→        const refugeeStrain = Math.min(0.4, region.refugeesHosted / region.population);
  1376→        regionShelter -= refugeeStrain;
  1377→      }
  1378→      
  1379→      // Thermal habitability varies by latitude
  1380→      // Tropical regions hit harder by temperature rise
  1381→      const isTropical = region.name.includes('Africa') || 
  1382→                         region.name.includes('South Asia') || 
  1383→                         region.name.includes('Southeast Asia') ||
  1384→                         region.name.includes('Middle East');
  1385→      let regionHabitability = survivalFundamentals.thermalHabitability;
  1386→      if (isTropical) {
  1387→        const tempAnomaly = state.resourceEconomy.co2.temperatureAnomaly;
  1388→        if (tempAnomaly > 1.5) {
  1389→          // Tropical regions become uninhabitable faster
  1390→          regionHabitability *= Math.max(0.3, 1 - (tempAnomaly - 1.5) * 0.25);
  1391→        }
  1392→      }
  1393→      
  1394→      // Survival fundamentals contribution (40% weight)
  1395→      const survivalScore = (
  1396→        regionFoodSecurity * 0.30 +
  1397→        regionWaterSecurity * 0.30 +
  1398→        regionHabitability * 0.25 +
  1399→        regionShelter * 0.15
  1400→      );
  1401→      
  1402→      // === BASIC NEEDS (30% weight) ===
  1403→      // Modified by economic access and infrastructure
  1404→      let regionMaterial = basicQoL.materialAbundance;
  1405→      let regionEnergy = basicQoL.energyAvailability;
  1406→      let regionSafety = basicQoL.physicalSafety;
  1407→      
  1408→      // Conflict-affected regions have low safety
  1409→      if (region.conflictRisk > 0.5) {
  1410→        regionSafety *= (1 - region.conflictRisk * 0.6);
  1411→      }
  1412→      
  1413→      // Population stress reduces material abundance
  1414→      if (region.populationStress > 0.7) {
  1415→        regionMaterial *= (1 - region.populationStress * 0.3);
  1416→        regionEnergy *= (1 - region.populationStress * 0.2);
  1417→      }
  1418→      
  1419→      const basicNeedsScore = (
  1420→        regionMaterial * 0.4 +
  1421→        regionEnergy * 0.3 +
  1422→        regionSafety * 0.3
  1423→      );
  1424→      
  1425→      // === HEALTH & WELLBEING (30% weight) ===
  1426→      // Modified by regional capacity and crisis impacts
  1427→      let regionHealth = basicQoL.healthcareQuality;
  1428→      let regionMentalHealth = basicQoL.mentalHealth;
  1429→      
  1430→      // Crisis zones have worse mental health
  1431→      const inCrisisZone = region.droughtAffected || 
  1432→                          region.conflictRisk > 0.5 || 
  1433→                          region.populationStress > 0.7;
  1434→      if (inCrisisZone) {
  1435→        regionMentalHealth *= 0.6; // 40% reduction
  1436→        totalCrisisAffected += region.population;
  1437→      }
  1438→      
  1439→      // Healthcare capacity varies by development
  1440→      // Assume wealthier regions have 1.3x capacity, poorer 0.7x
  1441→      const isWealthy = region.name.includes('North America') || 
  1442→                       region.name.includes('Europe') || 
  1443→                       region.name.includes('East Asia');
  1444→      regionHealth *= isWealthy ? 1.2 : 0.8;
  1445→      
  1446→      const healthScore = (
  1447→        regionHealth * 0.6 +
  1448→        regionMentalHealth * 0.4
  1449→      );
  1450→      
  1451→      // === AGGREGATE REGION QOL ===
  1452→      regionQoL = (
  1453→        survivalScore * 0.40 +
  1454→        basicNeedsScore * 0.30 +
  1455→        healthScore * 0.30
  1456→      );
  1457→      
  1458→      regionalQoLs.push(Math.max(0, Math.min(2, regionQoL)));
  1459→    }
  1460→  } else {
  1461→    // Fallback: Use simple crisis-based approximation
  1462→    // This handles cases where regional system isn't fully initialized
  1463→    const avgQoL = (
  1464→      survivalFundamentals.foodSecurity * 0.15 +
  1465→      survivalFundamentals.waterSecurity * 0.15 +
  1466→      survivalFundamentals.thermalHabitability * 0.10 +
  1467→      basicQoL.materialAbundance * 0.15 +
  1468→      basicQoL.energyAvailability * 0.10 +
  1469→      basicQoL.physicalSafety * 0.10 +
  1470→      basicQoL.mentalHealth * 0.10 +
