   133→    // Check if cascading crises make recovery impossible
   134→    if (hasIrreversibleCascade(state)) {
   135→      console.log(`   ⚰️  TERMINAL: Extinction likely (${(currentPeople / 1_000_000).toFixed(1)}M people, ${(mortality * 100).toFixed(1)}% mortality, irreversible cascade)\n`);
   136→      return 'terminal';
   137→    }
   138→    console.log(`   🧬 BOTTLENECK: Genetic bottleneck (${(currentPeople / 1_000_000).toFixed(1)}M people, ${(mortality * 100).toFixed(1)}% mortality)\n`);
   139→    return 'bottleneck';
   140→  }
   141→  
   142→  // BOTTLENECK: 87.5-98.75% mortality (100M-1B people)
   143→  if (mortality > 0.875 || currentPeople < 1_000_000_000) {
   144→    console.log(`   🧬 BOTTLENECK: Genetic bottleneck (${(currentPeople / 1_000_000).toFixed(0)}M people, ${(mortality * 100).toFixed(1)}% mortality)\n`);
