   208→ *
   209→ * Distinguishes humane (prosperity without mass death) vs pyrrhic (recovery after catastrophe) outcomes
   210→ *
   211→ * Research:
   212→ * - Wilkinson & Pickett (2009): Extreme disruption (>20% mortality) causes decades of trauma
   213→ * - Rawls (1971): Distributive justice requires examining worst-off groups
   214→ * - Historical precedents: Black Death (30-60%), Spanish Flu (3-5%), WWII (3%)
   215→ *
   216→ * @param state - Current game state
   217→ * @param baseOutcome - The base outcome classification (utopia/dystopia/extinction/inconclusive)
   218→ * @param initialPopulation - Starting population (8.0B)
   219→ */
   220→function classifyStratifiedOutcome(
   221→  state: GameState,
   222→  baseOutcome: 'utopia' | 'dystopia' | 'extinction' | 'inconclusive',
   223→  initialPopulation: number
   224→): { stratifiedOutcome: import('@/types/game').StratifiedOutcomeType; mortalityBand: import('@/types/game').MortalityBand } {
   225→  const finalPopulation = state.humanPopulationSystem.population; // in billions
   226→  const mortalityRate = 1 - (finalPopulation / initialPopulation);
   227→  const finalPopulationPeople = finalPopulation * 1_000_000_000;
   228→
   229→  // Determine mortality band
   230→  let mortalityBand: import('@/types/game').MortalityBand;
   231→  if (mortalityRate < 0.20) {
   232→    mortalityBand = 'low';
   233→  } else if (mortalityRate < 0.50) {
   234→    mortalityBand = 'moderate';
   235→  } else if (mortalityRate < 0.75) {
   236→    mortalityBand = 'high';
   237→  } else if (mortalityRate < 0.90) {
   238→    mortalityBand = 'extreme';
   239→  } else {
   240→    mortalityBand = 'bottleneck';
   241→  }
