  console.log(`  🌾 Food system under stress: ${activeCrises} active crises, degradation ${(foodDegradationRate * 100).toFixed(1)}%/month`);
}

qol.healthcareQuality = Math.max(0, qol.healthcareQuality * 0.98);
qol.physicalSafety = Math.max(0, qol.physicalSafety * 0.97);
