/**
 * Debug script to track food security values throughout a simulation run
 *
 * Logs:
 * - Food security value each month
 * - Active crises
 * - Population levels
 * - Infrastructure penalties
 * - When famines should trigger (< 0.6)
 */

import { initializeGameState } from '../src/simulation/initialization';
import { updateGameState } from '../src/simulation';
import { GameState } from '../src/types/game';
import { seedRandom } from '../src/simulation/utils/random';

async function debugFoodSecurity() {
  console.log('\n=== FOOD SECURITY DEBUG RUN ===\n');

  // Initialize with fixed seed for reproducibility
  const seed = 42000;
  const rng = seedRandom(seed);

  let state: GameState = initializeGameState(seed);

  console.log(`Seed: ${seed}`);
  console.log(`Starting food security: ${(state.survivalFundamentals?.foodSecurity ?? 0).toFixed(3)}`);
  console.log(`Starting population: ${state.humanPopulationSystem.population.toFixed(3)}B\n`);

  // Run for 120 months, logging food security
  for (let month = 1; month <= 120; month++) {
    state = updateGameState(state, rng);

    const foodSec = state.survivalFundamentals?.foodSecurity ?? 0;
    const pop = state.humanPopulationSystem.population;
    const popRatio = pop / 8.0;

    // Log every month, highlighting critical values
    if (foodSec < 0.65 || month % 12 === 0) {
      console.log(`\n[Month ${month}] Food Security: ${foodSec.toFixed(3)} ${foodSec < 0.6 ? '⚠️ BELOW FAMINE THRESHOLD' : ''}`);
      console.log(`  Population: ${pop.toFixed(3)}B (${(popRatio * 100).toFixed(1)}% of 8B)`);

      // Check active crises
      const activeCrises = [
        state.crises?.phosphorusCrisis?.active ? 'phosphorus' : null,
        state.crises?.freshwaterCrisis?.active ? 'freshwater' : null,
        state.crises?.biodiversityCrisis?.active ? 'biodiversity' : null,
        state.environmentalAccumulation?.tipSurpassed ? 'tipping point' : null,
      ].filter(Boolean);

      if (activeCrises.length > 0) {
        console.log(`  Active crises (${activeCrises.length}): ${activeCrises.join(', ')}`);
      }

      // Check for active famines
      const activeFamines = state.famineSystem?.activeFamines?.length ?? 0;
      if (activeFamines > 0) {
        console.log(`  ✅ Active famines: ${activeFamines}`);
      }

      // Check food stock
      if (state.resourceEconomy?.food) {
        console.log(`  Food stock: ${state.resourceEconomy.food.currentStock.toFixed(1)}`);
      }
    }

    // Stop if extinction
    if (state.extinctionState.extinct) {
      console.log(`\n💀 EXTINCTION at month ${month}`);
      console.log(`  Final food security: ${foodSec.toFixed(3)}`);
      console.log(`  Final population: ${pop.toFixed(3)}B`);
      break;
    }
  }

  console.log('\n=== DEBUG RUN COMPLETE ===\n');
}

debugFoodSecurity().catch(console.error);

