import { seedRandom } from '../src/simulation/utils/random';

async function debugFoodSecurity() {
  console.log('\n=== FOOD SECURITY DEBUG RUN ===\n');

  // Initialize with fixed seed for reproducibility
  const seed = 42000;
  const rng = seedRandom(seed);

  let state: GameState = initializeGameState(seed);

