   137→      return 'terminal';
   138→    }
   139→    console.log(`   🧬 BOTTLENECK: Genetic bottleneck (${(currentPeople / 1_000_000).toFixed(1)}M people, ${(mortality * 100).toFixed(1)}% mortality)\n`);
