   154→      return 'dark_age';
   155→    }
   156→    console.log(`   💥 COLLAPSE: Major systems failing (${(currentPop).toFixed(2)}B people, ${(mortality * 100).toFixed(1)}% mortality)\n`);
   157→    return 'collapse';
   158→  }
   159→  
   160→  // COLLAPSE: 20-50% mortality (4B-6.4B people)
   161→  if (mortality > 0.20) {
   162→    console.log(`   💥 COLLAPSE: Major crisis (${(currentPop).toFixed(2)}B people, ${(mortality * 100).toFixed(1)}% mortality)\n`);
   163→    return 'collapse';
   164→  }
   165→  
   166→  // CRISIS ERA: 10-20% mortality (6.4B-7.2B people)
   167→  if (mortality > 0.10) {
