      console.log(`  🌾 Food system under stress: ${activeCrises} active crises, degradation ${(degradationRate * 100).toFixed(1)}%/month`);
      console.log(`     Food security: ${(currentFoodSec * 100).toFixed(1)}% → ${(newFoodSec * 100).toFixed(1)}%`);
    }

    return { events: [] };
  }
}

