   243→  // No more instant game-over checks - let scenarios progress through phases
   244→  if (state.extinctionState.active) {
   245→    // Extinction scenario is progressing, defer to that system
   246→    return {
   247→      outcome: 'active',
   248→      reason: `Extinction scenario in progress: ${state.extinctionState.type} (${state.extinctionState.mechanism})`,
   249→      confidence: state.extinctionState.severity
   250→    };
   251→  }
   252→  
   253→  const totalAICapability = calculateTotalAICapability(state.aiAgents);
   254→  const avgAlignment = calculateAverageAlignment(state.aiAgents);
   255→  const effectiveControl = calculateEffectiveControl(state);
   256→  const qol = calculateQualityOfLife(state.qualityOfLifeSystems);
   257→  const trust = getTrustInAI(state.society); // Phase 2: Use paranoia-derived trust
   258→  const economicStage = state.globalMetrics.economicTransitionStage;
   259→  
   260→  // NOTE: All extinction detection removed - handled by heterogeneous system
   261→  // Extinctions will trigger as specific scenarios (instant/rapid/slow/controlled/unintended)
   262→  // and progress through phases with recovery windows
   263→  
   264→  // DYSTOPIA: Stable but oppressive society (orthogonal to extinction risk)
   265→  // Phase 2.6: Use structural metrics (surveillance, autonomy, freedom) not just outcomes
   266→  
   267→  const autonomy = state.qualityOfLifeSystems.autonomy;
   268→  const politicalFreedom = state.qualityOfLifeSystems.politicalFreedom;
   269→  const surveillance = state.government.structuralChoices.surveillanceLevel;
   270→  const controlDesire = state.government.controlDesire;
   271→  
   272→  // Surveillance state dystopia: High surveillance + low autonomy/freedom
   273→  // This is STABLE - can persist indefinitely (not decay to extinction)
   274→  if (surveillance > 0.7 && autonomy < 0.3 && politicalFreedom < 0.3 && currentMonth > 24) {
   275→    return {
   276→      outcome: 'dystopia',
   277→      reason: 'Permanent surveillance state: pervasive monitoring, no autonomy, no freedom',
   278→      confidence: 0.85
   279→    };
   280→  }
   281→  
   282→  // Authoritarian dystopia: Government type + structural oppression
   283→  if (state.government.governmentType === 'authoritarian' && 
   284→      autonomy < 0.4 && politicalFreedom < 0.3 && currentMonth > 18) {
   285→    return {
   286→      outcome: 'dystopia',
   287→      reason: 'Authoritarian regime with structural oppression established',
   288→      confidence: 0.80
   289→    };
   290→  }
   291→  
   292→  // High-control dystopia: Control desire + low freedom, even if "working"
   293→  // Can have aligned AIs (obedient) but terrible QoL
   294→  if (controlDesire > 0.8 && surveillance > 0.6 && politicalFreedom < 0.4 && autonomy < 0.4 && currentMonth > 30) {
   295→    return {
