    crisisAffectedFraction: number;     // [0,1] % population in crisis zones
    worstRegionQoL: number;             // [0,2] Worst-off region (Rawlsian minimum)
    bestRegionQoL: number;              // [0,2] Best-off region
    medianRegionQoL: number;            // [0,2] Median region
